window.BDGottmanBids98={"version":"15.12.98","title":"Gottman Level 2 · Bids & Turning Praxislab","topics":[{"id":"silent","name":"Stilles Kontaktangebot","section":"4.3.1","core":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","signal":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","ask":"Haben Sie bemerkt, dass gerade ohne Worte Kontakt angeboten wurde?","best":"Ein sichtbares stilles Angebot beschreiben, B nach eigener Wahrnehmung fragen.","next":"Ein kleines willkommenes nonverbales Kontaktangebot ausprobieren.","caution":"Ein flüchtiger Blick ohne Kontaktabsicht ist nicht zwingend ein Bid.","near":["comment_low","passive","nonbid"]},{"id":"comment_low","name":"Sachlicher Kommentar","section":"4.3.2","core":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","signal":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","ask":"War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","best":"Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten.","next":"Eine kurze zugewandte Antwort auf einen sachlichen Kommentar üben.","caution":"Nicht jeder gesprochene Satz ist eine Bitte um tiefes Gespräch.","near":["comment_high","question_low","nonbid"]},{"id":"comment_high","name":"Persönlicher Kommentar","section":"4.3.2","core":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","signal":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","ask":"Was war Ihnen daran persönlich wichtig?","best":"Persönlichen Gehalt aufnehmen und neugierig weiterfragen.","next":"Im Alltag eine kurze persönliche Selbstmitteilung beantworten.","caution":"Hohes Level meint Inhalt, nicht unbedingt Lautstärke oder Aufregung.","near":["comment_low","question_high","attentive"]},{"id":"question_low","name":"Informationsfrage","section":"4.3.3","core":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","signal":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","ask":"Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","best":"Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation.","next":"Einfach und freundlich Auskunft geben, danach Raum für mehr lassen.","caution":"Eine Frage nach Fakten ist nicht automatisch ein Vorwurf oder Intimitätsangebot.","near":["question_high","comment_low","low_energy"]},{"id":"question_high","name":"Frage nach Gedanken oder Gefühlen","section":"4.3.3","core":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","signal":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","ask":"Welche eigene Bedeutung könnte diese Frage für B haben?","best":"Die subjektive Antwort neugierig aufnehmen, statt nur Fakten auszutauschen.","next":"Eine offene persönliche Anschlussfrage gemeinsam ausprobieren.","caution":"Eine kurze Frage kann persönlich sein, auch wenn sie sachlich klingt.","near":["question_low","comment_high","attentive"]},{"id":"playful_bid","name":"Spielerisches Kontaktangebot","section":"4.3.4","core":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","signal":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","ask":"War das Spiel für beide lustig und freiwillig?","best":"Gemeinsamen Humor als Ressource würdigen, ohne Zustimmung vorauszusetzen.","next":"Einen leichten beidseitig willkommenen spielerischen Moment ermöglichen.","caution":"Humor mit Beschämung, Druck oder unerwünschter Berührung ist kein unproblematisches Spiel.","near":["question_low","against_belligerence","playful_response"]},{"id":"negative_bid","name":"Negatives Kontaktangebot","section":"4.3.5","core":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","signal":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","ask":"Was wird hier zum Kontaktangebot, obwohl es gleichzeitig verletzt?","best":"Abwertung begrenzen und das mögliche Anliegen dahinter vorsichtig erfragen.","next":"Eine konkrete Beschwerde ohne persönliche Herabsetzung formulieren.","caution":"Sicherheit, Einschüchterung und Machtgefälle gehen vor Kommunikationsübungen.","near":["against_criticism","against_domineering","comment_high"]},{"id":"rebid","name":"Erneutes gleiches Kontaktangebot","section":"4.3.6","core":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","signal":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","ask":"Was wurde beim ersten Versuch angeboten und wie wurde darauf reagiert?","best":"Erste Reaktion benennen, wiederholtes Angebot würdigen und nach Wirkung fragen.","next":"Eine freundliche Antwort auf ein wiederholtes Angebot erproben.","caution":"Ein neuer Themenwechsel ist kein Rebid desselben Anliegens.","near":["question_low","away_preoccupied","dropout"]},{"id":"dropout","name":"Abrupter Gesprächsabbruch","section":"4.3.7","core":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","signal":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","ask":"War das ein natürlicher Abschluss oder ein abrupter Kontaktabbruch?","best":"Den Bruch behutsam markieren und den Grund erfragen, ohne Absicht festzulegen.","next":"Eine freiwillige Pause mit Wiedereinstiegsmöglichkeit vereinbaren.","caution":"Von Drop-out nicht automatisch auf Desinteresse schließen: Überforderung und Schutz prüfen.","near":["away_disregard","away_preoccupied","passive"]},{"id":"passive","name":"Passives Hinwenden","section":"4.4.1","core":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","signal":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","ask":"Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","best":"Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen.","next":"Erkunden, welche kleinen Signale bei wenig Energie dennoch Verbindung zeigen.","caution":"Wenn A die minimale Reaktion gar nicht wahrnehmen kann, passt eher Turning Away.","near":["low_energy","away_preoccupied","attentive"]},{"id":"low_energy","name":"Knappes sachliches Hinwenden","section":"4.4.2","core":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","signal":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","ask":"Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","best":"Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen.","next":"Kleine praktische Kontaktreaktion als legitime Antwort anerkennen.","caution":"Low Energy ist kein Zeichen mangelnder Liebe; Personen haben verschiedene Ausdrucksstile.","near":["passive","attentive","question_low"]},{"id":"attentive","name":"Aufmerksames Hinwenden","section":"4.4.3","core":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","signal":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","ask":"Was genau macht das Zuhören für A hier spürbar?","best":"Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen.","next":"Eine interessierte Anschlussfrage im Alltag üben.","caution":"Aufmerksamkeit lässt sich nicht aus Blickkontakt allein ableiten.","near":["low_energy","enthusiastic","question_high"]},{"id":"enthusiastic","name":"Begeistertes Hinwenden","section":"4.4.4","core":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","signal":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","ask":"Wie wirkt diese Energie auf die Person, die das Angebot gemacht hat?","best":"Freude als Ressource nutzen; Intensität an gegenseitige Passung anpassen.","next":"Einen gemeinsamen positiven Moment bewusst würdigen.","caution":"Viel Energie ist nicht für jede Person angenehm; Wirkung und Reizbelastung beachten.","near":["attentive","playful_response","low_energy"]},{"id":"playful_response","name":"Spielerische Erwiderung","section":"4.4.5","core":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","signal":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","ask":"Wie zeigen beide, dass das Spiel für sie willkommen ist?","best":"Die wechselseitige Zustimmung und geteilte Freude wahrnehmen.","next":"Ein kleines Spielangebot ohne Druck gestalten.","caution":"Körperliche Reaktion muss einvernehmlich sein, keine Überraschungsberührung voraussetzen.","near":["enthusiastic","playful_bid","boundary"]},{"id":"against_contempt","name":"Hinwenden gegen die Person: Verachtung","section":"4.5.1","core":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","signal":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","ask":"Welcher Satz verletzt gerade Würde und Gleichwertigkeit?","best":"Abwertung klar begrenzen und die zugrunde liegende Beschwerde konkretisieren.","next":"Eine konkrete nicht-abwertende Antwort anbieten.","caution":"Herabsetzung nicht durch Humor oder „ehrliche Meinung“ legitimieren.","near":["against_criticism","against_belligerence","negative_bid"]},{"id":"against_belligerence","name":"Hinwenden als Kampfansage","section":"4.5.2","core":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","signal":"B antwortet auf Kontakt mit offensiver Provokation.","ask":"Wird hier gerade Verbindung gesucht oder eine Auseinandersetzung angeheizt?","best":"Den Machtkampf unterbrechen, sicheren Rahmen und Tempo vereinbaren.","next":"Statt der Kampfansage eine überprüfbare Bitte formulieren.","caution":"Bei Drohungen vor jeder Dialogübung gezielt Sicherheit abklären.","near":["against_contempt","against_domineering","negative_bid"]},{"id":"against_domineering","name":"Hinwenden als Kontrolle","section":"4.5.3","core":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","signal":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","ask":"Wessen Wahlfreiheit wird gerade eingeschränkt?","best":"Machtanspruch und Freiwilligkeit klären; bei Zwang Sicherheit priorisieren.","next":"Eine gleichberechtigte Gesprächsvereinbarung erarbeiten, falls sicher.","caution":"Kontrollverhalten bei Furcht, Isolation oder Drohungen nicht als normalen Streit behandeln.","near":["against_belligerence","against_criticism","boundary"]},{"id":"against_criticism","name":"Hinwenden als Charakterkritik","section":"4.5.4","core":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","signal":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","ask":"Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","best":"Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten.","next":"Eine konkrete Beobachtung und eigene Bitte formulieren.","caution":"Nicht jede ärgerliche Beschwerde ist Kritik im Sinne eines Persönlichkeitsangriffs.","near":["against_contempt","against_defensiveness","negative_bid"]},{"id":"against_defensiveness","name":"Hinwenden als Abwehr","section":"4.5.5","core":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","signal":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","ask":"Welche Befürchtung hört B in der eigentlichen Äußerung?","best":"Abwehr anerkennen, ursprüngliche Bitte wieder sichtbar machen und Verantwortung differenzieren.","next":"Einen nicht-defensiven Zuhörsatz ausprobieren.","caution":"Bei realen Anschuldigungen nicht automatisch gleiche Verantwortung unterstellen.","near":["against_criticism","low_energy","attentive"]},{"id":"away_preoccupied","name":"Abwesend durch Beschäftigung","section":"4.6.1","core":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","signal":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","ask":"War die Einladung für B überhaupt wahrnehmbar?","best":"Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","next":"Aufmerksamkeitsfenster und hilfreiches Ansprechen abstimmen.","caution":"Arbeit, Schwerhörigkeit oder Neurodiversität sind keine Beweise fehlender Bindung.","near":["passive","away_disregard","rebid"]},{"id":"away_interrupt","name":"Unterbrechendes Abwenden","section":"4.6.2","core":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","signal":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","ask":"Was ist mit dem ursprünglichen Angebot passiert?","best":"Unterbrechung freundlich sichtbar machen; As Aussage wieder Raum geben.","next":"Ein einfaches Zuhörsignal und Wiedereinstieg vereinbaren.","caution":"Unterbrechung kann auch aus Stress oder Kommunikationsstil entstehen; Muster prüfen.","near":["away_preoccupied","away_disregard","attentive"]},{"id":"away_disregard","name":"Ignorierendes Abwenden","section":"4.6.3","core":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","signal":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","ask":"Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","best":"Beobachtung benennen, Wirkung erfragen und Gründe offenlassen.","next":"Ein beidseitig verständliches Signal für „gehört, später“ vereinbaren.","caution":"Keine Absicht aus Schweigen beweisen; Sicherheit, Aufmerksamkeit und individuelle Unterschiede prüfen.","near":["away_preoccupied","passive","dropout"]},{"id":"nonbid","name":"Kein an Partner gerichtetes Bid","section":"4.2.3","core":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","signal":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","ask":"Wurde hier überhaupt ein Kontaktversuch an B gemacht?","best":"Nicht jedes Verhalten als Beziehungssignal werten; die tatsächliche Adressierung klären.","next":"Unterscheiden, wann Gesprächsbeobachtung überhaupt ein Bid umfasst.","caution":"Nicht aus Selbstgesprächen, Telefonaten oder flüchtigen Blicken Bids machen.","near":["silent","comment_low","away_preoccupied"]},{"id":"boundary","name":"Freiwillige Grenze statt Zurückweisung","section":"4.2 / 4.4–4.6; professionelle Ergänzung","core":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","signal":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","ask":"Welche Grenze wird gesetzt, und welche Verbindung bleibt möglich?","best":"Das Nein als gültige Grenze anerkennen; nicht als Liebesentzug interpretieren.","next":"Freiwilligen Wiedereinstieg oder anderen Kontaktweg vereinbaren.","caution":"Bei Druck, Angst, kontrollierendem Verhalten oder Zwang keine „Turning-Toward-Pflicht“ vermitteln.","near":["away_disregard","low_energy","attentive"]}],"cases":[{"id":"gb98-silent-01","domain":"silent","pivot":"attentive","topic":"Stilles Kontaktangebot","key":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","section":"4.3.1","line":"A zeigt wortlos ein Foto vom ersten gemeinsamen Urlaub.","reply":"B tippt weiter auf dem Tablet.","observation":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","twist":"B erkennt später das Foto und will wissen, warum es A wichtig war.","lead":1,"other":6},{"id":"gb98-silent-02","domain":"silent","pivot":"nonbid","topic":"Stilles Kontaktangebot","key":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","section":"4.3.1","line":"A hält B lächelnd die handgeschriebene Einladung hin.","reply":"B schaut kurz hoch.","observation":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","twist":"B dachte, es sei Werbung, und hat die persönliche Einladung übersehen.","lead":2,"other":7},{"id":"gb98-silent-03","domain":"silent","pivot":"away_preoccupied","topic":"Stilles Kontaktangebot","key":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","section":"4.3.1","line":"A deutet auf den ersten Schnee vor dem Fenster.","reply":"B schaut in die andere Richtung.","observation":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","twist":"B trägt gerade ein Hörgerät nicht und hatte die Geste nicht wahrgenommen.","lead":3,"other":8},{"id":"gb98-silent-04","domain":"silent","pivot":"boundary","topic":"Stilles Kontaktangebot","key":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","section":"4.3.1","line":"A streckt die offene Hand über den Tisch, ohne B zu berühren.","reply":"B hält die Hände zunächst bei sich.","observation":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","twist":"B erklärt, heute keine Berührung zu wollen, aber gern zu sprechen.","lead":4,"other":9},{"id":"gb98-silent-05","domain":"silent","pivot":"comment_high","topic":"Stilles Kontaktangebot","key":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","section":"4.3.1","line":"A legt B vorsichtig einen gefundenen Erinnerungsgegenstand auf den Tisch.","reply":"B nickt abwesend.","observation":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","twist":"B erzählt anschließend, welche schöne Erinnerung damit verbunden ist.","lead":5,"other":10},{"id":"gb98-comment_low-01","domain":"comment_low","pivot":"comment_high","topic":"Sachlicher Kommentar","key":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","section":"4.3.2","line":"Der Bus kommt heute zehn Minuten später.","reply":"Gut, dann müssen wir nicht rennen.","observation":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","twist":"A ergänzt: „Ich wollte eigentlich noch kurz bei dir sitzen.“","lead":6,"other":11},{"id":"gb98-comment_low-02","domain":"comment_low","pivot":"attentive","topic":"Sachlicher Kommentar","key":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","section":"4.3.2","line":"Die Pflanzen auf dem Balkon bekommen neue Blätter.","reply":"Stimmt, die wachsen gerade schnell.","observation":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","twist":"B legt das Telefon weg und fragt, welche Pflanze A besonders mag.","lead":7,"other":0},{"id":"gb98-comment_low-03","domain":"comment_low","pivot":"comment_high","topic":"Sachlicher Kommentar","key":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","section":"4.3.2","line":"Morgen ist unser Termin um neun.","reply":"Ich habe ihn eingetragen.","observation":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","twist":"A sagt, dass die gemeinsame Planung zuletzt selten gelang.","lead":8,"other":1},{"id":"gb98-comment_low-04","domain":"comment_low","pivot":"comment_high","topic":"Sachlicher Kommentar","key":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","section":"4.3.2","line":"Die neuen Nachbarn haben die Wohnung gestrichen.","reply":"Das habe ich gesehen.","observation":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","twist":"B erzählt später, dass A solche kleinen Alltagsgespräche vermisst.","lead":9,"other":2},{"id":"gb98-comment_low-05","domain":"comment_low","pivot":"comment_high","topic":"Sachlicher Kommentar","key":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","section":"4.3.2","line":"Das Brot ist noch warm.","reply":"Dann nehme ich gern ein Stück.","observation":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","twist":"A gesteht, besonders auf ein gemeinsames Frühstück gehofft zu haben.","lead":10,"other":3},{"id":"gb98-comment_high-01","domain":"comment_high","pivot":"attentive","topic":"Persönlicher Kommentar","key":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","section":"4.3.2","line":"Ich liebe diesen ruhigen Moment vor der Arbeit.","reply":"Ich bin um die Uhrzeit eher noch müde.","observation":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","twist":"B fragt nach, was A an dieser Zeit so gefällt.","lead":11,"other":4},{"id":"gb98-comment_high-02","domain":"comment_high","pivot":"attentive","topic":"Persönlicher Kommentar","key":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","section":"4.3.2","line":"Ich war stolz, als du heute das Problem ruhig gelöst hast.","reply":"Danke, das freut mich.","observation":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","twist":"A sagt, solche Worte kämen selten vor.","lead":0,"other":5},{"id":"gb98-comment_high-03","domain":"comment_high","pivot":"question_high","topic":"Persönlicher Kommentar","key":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","section":"4.3.2","line":"Mir bedeutet unser gemeinsames Kochen sehr viel.","reply":"Für mich ist es manchmal nur Stress.","observation":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","twist":"Beide entdecken unterschiedliche Bedeutungen desselben Rituals.","lead":1,"other":6},{"id":"gb98-comment_high-04","domain":"comment_high","pivot":"attentive","topic":"Persönlicher Kommentar","key":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","section":"4.3.2","line":"Ich habe das Gefühl, mein neues Hobby verändert mich.","reply":"Davon hast du noch wenig erzählt.","observation":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","twist":"B interessiert sich nun ehrlich für diese Entwicklung.","lead":2,"other":7},{"id":"gb98-comment_high-05","domain":"comment_high","pivot":"passive","topic":"Persönlicher Kommentar","key":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","section":"4.3.2","line":"Ich finde den geplanten Umzug gleichzeitig aufregend und beängstigend.","reply":"Ich merke, wir erleben das unterschiedlich.","observation":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","twist":"B sagt, seine erste knappe Reaktion sei aus Überforderung entstanden.","lead":3,"other":8},{"id":"gb98-question_low-01","domain":"question_low","pivot":"comment_high","topic":"Informationsfrage","key":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","section":"4.3.3","line":"Wann fährt dein Zug am Sonntag?","reply":"Um halb sieben am Abend.","observation":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","twist":"A erklärt, B gern noch zum Bahnhof begleiten zu wollen.","lead":4,"other":9},{"id":"gb98-question_low-02","domain":"question_low","pivot":"attentive","topic":"Informationsfrage","key":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","section":"4.3.3","line":"Hast du den Schlüssel für den Proberaum?","reply":"Ja, er liegt in meiner Tasche.","observation":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","twist":"B fragt, ob A über das Projekt sprechen möchte.","lead":5,"other":10},{"id":"gb98-question_low-03","domain":"question_low","pivot":"comment_high","topic":"Informationsfrage","key":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","section":"4.3.3","line":"Ist das Treffen heute online oder vor Ort?","reply":"Vor Ort, im Seminarraum.","observation":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","twist":"A berichtet, das gemeinsame Planen sei früher selbstverständlich gewesen.","lead":6,"other":11},{"id":"gb98-question_low-04","domain":"question_low","pivot":"attentive","topic":"Informationsfrage","key":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","section":"4.3.3","line":"Wie viele Gäste kommen am Samstag?","reply":"Acht haben zugesagt.","observation":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","twist":"B bietet an, einen Teil der Vorbereitung zu übernehmen.","lead":7,"other":0},{"id":"gb98-question_low-05","domain":"question_low","pivot":"question_high","topic":"Informationsfrage","key":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","section":"4.3.3","line":"Kannst du mir die Adresse schicken?","reply":"Ich sende sie gleich.","observation":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","twist":"A bedankt sich und sucht dann ein persönlicheres Gespräch.","lead":8,"other":1},{"id":"gb98-question_high-01","domain":"question_high","pivot":"attentive","topic":"Frage nach Gedanken oder Gefühlen","key":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","section":"4.3.3","line":"Wie fühlst du dich mit der Entscheidung für die neue Wohnung?","reply":"Ich freue mich, habe aber Bedenken.","observation":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","twist":"A nimmt sich überraschend Zeit, die Bedenken zu hören.","lead":9,"other":2},{"id":"gb98-question_high-02","domain":"question_high","pivot":"boundary","topic":"Frage nach Gedanken oder Gefühlen","key":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","section":"4.3.3","line":"Magst du eigentlich die Wochenenden mit meiner Familie?","reply":"Manchmal ist es mir dort zu laut.","observation":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","twist":"A fragt, welche Gestaltung B besser passen würde.","lead":10,"other":3},{"id":"gb98-question_high-03","domain":"question_high","pivot":"comment_high","topic":"Frage nach Gedanken oder Gefühlen","key":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","section":"4.3.3","line":"Was bedeutet dir dein Geburtstag dieses Jahr?","reply":"Ich möchte ihn eher ruhig verbringen.","observation":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","twist":"B erzählt von einer belastenden Erfahrung mit früheren Feiern.","lead":11,"other":4},{"id":"gb98-question_high-04","domain":"question_high","pivot":"attentive","topic":"Frage nach Gedanken oder Gefühlen","key":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","section":"4.3.3","line":"Findest du unseren Alltag gerade zu eng getaktet?","reply":"Ja, ich vermisse Leerlauf.","observation":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","twist":"A erkennt, dass beide denselben Zeitdruck erleben.","lead":0,"other":5},{"id":"gb98-question_high-05","domain":"question_high","pivot":"question_high","topic":"Frage nach Gedanken oder Gefühlen","key":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","section":"4.3.3","line":"Was wünschst du dir für unseren freien Tag?","reply":"Ich würde gern ohne Plan losziehen.","observation":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","twist":"A nennt nun seine eigene Sorge vor ungeplanten Tagen.","lead":1,"other":6},{"id":"gb98-playful_bid-01","domain":"playful_bid","pivot":"playful_response","topic":"Spielerisches Kontaktangebot","key":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","section":"4.3.4","line":"A wirft B auf dem Sofa spielerisch ein weiches Kissen zu.","reply":"B wirft es lachend zurück.","observation":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","twist":"B sagt, dass er solche Albernheiten im Moment sehr genießt.","lead":2,"other":7},{"id":"gb98-playful_bid-02","domain":"playful_bid","pivot":"playful_response","topic":"Spielerisches Kontaktangebot","key":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","section":"4.3.4","line":"A zeichnet auf dem Einkaufszettel einen absurd großen Käse.","reply":"B malt ihm eine Krone.","observation":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","twist":"Beide lachen über ihren gemeinsamen Küchenwitz.","lead":3,"other":8},{"id":"gb98-playful_bid-03","domain":"playful_bid","pivot":"boundary","topic":"Spielerisches Kontaktangebot","key":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","section":"4.3.4","line":"A fordert B augenzwinkernd zu einem Mini-Tanz im Flur auf.","reply":"B macht zwei übertriebene Tanzschritte.","observation":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","twist":"B sagt später, er wolle manchmal erst gefragt werden.","lead":4,"other":9},{"id":"gb98-playful_bid-04","domain":"playful_bid","pivot":"comment_high","topic":"Spielerisches Kontaktangebot","key":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","section":"4.3.4","line":"A spricht mit erfundener Radiostimme die Abwaschaufgaben an.","reply":"B antwortet lachend als Nachrichtensprecherin.","observation":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","twist":"Ein ernster Punkt zur fairen Arbeitsteilung wird danach ruhig besprochen.","lead":5,"other":10},{"id":"gb98-playful_bid-05","domain":"playful_bid","pivot":"attentive","topic":"Spielerisches Kontaktangebot","key":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","section":"4.3.4","line":"A balanciert spielerisch eine Serviette auf dem Kopf.","reply":"B lacht und versucht es ebenfalls.","observation":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","twist":"A bemerkt, dass B nach einem anstrengenden Tag wieder aufatmet.","lead":6,"other":11},{"id":"gb98-negative_bid-01","domain":"negative_bid","pivot":"against_criticism","topic":"Negatives Kontaktangebot","key":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","section":"4.3.5","line":"Na, hast du endlich gelernt, einen Termin einzutragen?","reply":"Ich möchte nicht so angesprochen werden.","observation":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","twist":"A sagt, hinter der Spitze stehe die Sorge um Verlässlichkeit.","lead":7,"other":0},{"id":"gb98-negative_bid-02","domain":"negative_bid","pivot":"against_contempt","topic":"Negatives Kontaktangebot","key":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","section":"4.3.5","line":"Du brauchst wohl wieder eine schriftliche Anleitung fürs Aufräumen.","reply":"Das macht mich klein.","observation":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","twist":"B berichtet, solche Spitzen seien fast täglich geworden.","lead":8,"other":1},{"id":"gb98-negative_bid-03","domain":"negative_bid","pivot":"comment_high","topic":"Negatives Kontaktangebot","key":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","section":"4.3.5","line":"Wenn du wirklich interessiert wärst, müsste ich dich nicht alles fragen.","reply":"Ich verstehe deine Enttäuschung, aber nicht diese Form.","observation":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","twist":"A kann nach einer Pause ein konkretes Bedürfnis benennen.","lead":9,"other":2},{"id":"gb98-negative_bid-04","domain":"negative_bid","pivot":"boundary","topic":"Negatives Kontaktangebot","key":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","section":"4.3.5","line":"Du bist natürlich wieder der einzige Mensch ohne Verantwortung.","reply":"Ich will über unsere Aufgaben sprechen, nicht über meinen Wert.","observation":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","twist":"B nennt eine eigene Grenze für weitere Gespräche.","lead":10,"other":3},{"id":"gb98-negative_bid-05","domain":"negative_bid","pivot":"against_domineering","topic":"Negatives Kontaktangebot","key":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","section":"4.3.5","line":"Los, beweis mir, dass dir die Beziehung etwas bedeutet!","reply":"Ich will keine Prüfung ablegen müssen.","observation":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","twist":"B beschreibt, dass solche Aufforderungen manchmal mit Drohungen verbunden sind.","lead":11,"other":4},{"id":"gb98-rebid-01","domain":"rebid","pivot":"away_preoccupied","topic":"Erneutes gleiches Kontaktangebot","key":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","section":"4.3.6","line":"A: Möchtest du nachher einen Spaziergang machen? B: Hm. A: Vielleicht nur zehn Minuten?","reply":"B: Ja, zehn Minuten gehen.","observation":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","twist":"B war vorher in Gedanken und hatte das erste Angebot kaum aufgenommen.","lead":0,"other":5},{"id":"gb98-rebid-02","domain":"rebid","pivot":"rebid","topic":"Erneutes gleiches Kontaktangebot","key":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","section":"4.3.6","line":"A: Soll ich dir einen Tee kochen? B schaut aufs Handy. A: Minze oder Ingwer?","reply":"B: Ingwer wäre schön.","observation":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","twist":"A berichtet, solche kleinen Angebote häufig wiederholen zu müssen.","lead":1,"other":6},{"id":"gb98-rebid-03","domain":"rebid","pivot":"attentive","topic":"Erneutes gleiches Kontaktangebot","key":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","section":"4.3.6","line":"A: Hast du kurz Zeit für meinen Tag? B: Später. A: Vielleicht nach dem Essen?","reply":"B: Nach dem Essen hören wir uns zu.","observation":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","twist":"B nennt eine konkrete Zeit und hält sie anschließend ein.","lead":2,"other":7},{"id":"gb98-rebid-04","domain":"rebid","pivot":"comment_high","topic":"Erneutes gleiches Kontaktangebot","key":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","section":"4.3.6","line":"A: Magst du das Bild sehen? B: Ja, gleich. A: Ich kann es dir hier zeigen.","reply":"B: Oh, das ist wirklich schön.","observation":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","twist":"A erzählt, die Bildfrage sei ein Wunsch nach gemeinsamem Erleben.","lead":3,"other":8},{"id":"gb98-rebid-05","domain":"rebid","pivot":"away_preoccupied","topic":"Erneutes gleiches Kontaktangebot","key":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","section":"4.3.6","line":"A: Können wir den Termin gemeinsam planen? B schweigt. A: Lieber heute Abend?","reply":"B: Heute Abend passt besser.","observation":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","twist":"B erklärt, die erste Frage im Arbeitsstress nicht verstanden zu haben.","lead":4,"other":9},{"id":"gb98-dropout-01","domain":"dropout","pivot":"dropout","topic":"Abrupter Gesprächsabbruch","key":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","section":"4.3.7","line":"A: Und dann hat die Ärztin mich beruhigt. B: Das freut mich. A: Außerdem … B verstummt plötzlich.","reply":"A: Du bist ganz weg.","observation":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","twist":"B erinnert sich an eine eigene belastende medizinische Nachricht.","lead":5,"other":10},{"id":"gb98-dropout-02","domain":"dropout","pivot":"away_preoccupied","topic":"Abrupter Gesprächsabbruch","key":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","section":"4.3.7","line":"A und B lachen über die Reise; mitten in As nächster Erinnerung legt B abrupt das Handy weg und schweigt.","reply":"A: Ist etwas passiert?","observation":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","twist":"B hat gerade eine Nachricht vom Arbeitgeber gelesen.","lead":6,"other":11},{"id":"gb98-dropout-03","domain":"dropout","pivot":"boundary","topic":"Abrupter Gesprächsabbruch","key":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","section":"4.3.7","line":"A: Wir könnten im Frühjahr fahren. B: Das wäre schön. A: Vielleicht mit dem Zug? B bricht ab.","reply":"A: Ich verliere gerade den Kontakt zu dir.","observation":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","twist":"B fühlt sich von der Entscheidung plötzlich unter Druck gesetzt.","lead":7,"other":0},{"id":"gb98-dropout-04","domain":"dropout","pivot":"dropout","topic":"Abrupter Gesprächsabbruch","key":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","section":"4.3.7","line":"A: Ich fand gestern schön. B: Ich auch. A: Besonders der Abend … B antwortet nicht mehr.","reply":"A: Soll ich einen Moment warten?","observation":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","twist":"B berichtet, sich im letzten Moment an einen Streit erinnert zu haben.","lead":8,"other":1},{"id":"gb98-dropout-05","domain":"dropout","pivot":"boundary","topic":"Abrupter Gesprächsabbruch","key":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","section":"4.3.7","line":"A: Also teilen wir die Aufgaben. B: Ja. A: Du machst den Einkauf und … B zieht sich unvermittelt zurück.","reply":"A: Ich merke, das Gespräch stockt.","observation":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","twist":"B beschreibt das Gefühl, seine Zustimmung sei vorausgesetzt worden.","lead":9,"other":2},{"id":"gb98-passive-01","domain":"passive","pivot":"passive","topic":"Passives Hinwenden","key":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","section":"4.4.1","line":"A: Schau, ein Regenbogen! B hebt kurz den Kopf und schaut wieder ins Buch.","reply":"A: Hast du ihn gesehen?","observation":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","twist":"B hat den Regenbogen bemerkt, ist aber erschöpft.","lead":10,"other":3},{"id":"gb98-passive-02","domain":"passive","pivot":"passive","topic":"Passives Hinwenden","key":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","section":"4.4.1","line":"A reicht B ein Foto; B nimmt es schweigend und nickt einmal.","reply":"A: Ich wollte dir erzählen, warum es mir wichtig ist.","observation":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","twist":"B sagt später, dass die Geste freundlich gemeint war.","lead":11,"other":4},{"id":"gb98-passive-03","domain":"passive","pivot":"away_preoccupied","topic":"Passives Hinwenden","key":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","section":"4.4.1","line":"A: Ich habe den Kuchen geschafft. B sagt, ohne aufzusehen, „Hm“.","reply":"A: Ich hätte mir ein bisschen Freude gewünscht.","observation":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","twist":"B hat A gehört, war aber gedanklich völlig absorbiert.","lead":0,"other":5},{"id":"gb98-passive-04","domain":"passive","pivot":"attentive","topic":"Passives Hinwenden","key":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","section":"4.4.1","line":"A: Die Katze macht schon wieder Unsinn. B schaut kurz hin und dann zurück.","reply":"A: Ich fand das lustig.","observation":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","twist":"B lacht erst nach einer weiteren Beschreibung.","lead":1,"other":6},{"id":"gb98-passive-05","domain":"passive","pivot":"passive","topic":"Passives Hinwenden","key":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","section":"4.4.1","line":"A: Morgen ist der große Tag. B nickt knapp und macht weiter.","reply":"A: Bist du bei mir?","observation":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","twist":"B sagt, die eigene Nervosität habe ihn wortkarg gemacht.","lead":2,"other":7},{"id":"gb98-low_energy-01","domain":"low_energy","pivot":"low_energy","topic":"Knappes sachliches Hinwenden","key":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","section":"4.4.2","line":"A: Brauchst du morgen das Auto? B legt den Stift weg: „Nein.“","reply":"A: Dann nehme ich es.","observation":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","twist":"B erklärt, während eines Projekts nicht ausführlicher reden zu können.","lead":3,"other":8},{"id":"gb98-low_energy-02","domain":"low_energy","pivot":"low_energy","topic":"Knappes sachliches Hinwenden","key":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","section":"4.4.2","line":"A bittet um eine Serviette. B steht auf und bringt sie kommentarlos.","reply":"A: Danke, das hat geholfen.","observation":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","twist":"B sagt, praktische Unterstützung sei seine spontane Art von Nähe.","lead":4,"other":9},{"id":"gb98-low_energy-03","domain":"low_energy","pivot":"comment_high","topic":"Knappes sachliches Hinwenden","key":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","section":"4.4.2","line":"A: Ist das Fenster offen? B dreht sich um: „Einen Spalt.“","reply":"A: Gut, dann bleibt es so.","observation":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","twist":"A berichtet, sich bei bloß praktischen Gesprächen oft einsam zu fühlen.","lead":5,"other":10},{"id":"gb98-low_energy-04","domain":"low_energy","pivot":"attentive","topic":"Knappes sachliches Hinwenden","key":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","section":"4.4.2","line":"A: Sind die Tickets angekommen? B stoppt die Musik: „Ja, beide.“","reply":"A: Prima.","observation":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","twist":"B schlägt später vor, gemeinsam die Route anzusehen.","lead":6,"other":11},{"id":"gb98-low_energy-05","domain":"low_energy","pivot":"low_energy","topic":"Knappes sachliches Hinwenden","key":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","section":"4.4.2","line":"A: Möchtest du Wasser? B setzt das Buch ab: „Gern.“","reply":"A: Ich bringe es gleich.","observation":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","twist":"B ist müde, fühlt sich aber gut versorgt.","lead":7,"other":0},{"id":"gb98-attentive-01","domain":"attentive","pivot":"attentive","topic":"Aufmerksames Hinwenden","key":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","section":"4.4.3","line":"A: Ich hatte ein schwieriges Gespräch. B legt die Zeitung weg: „Magst du erzählen?“","reply":"A: Ja, das würde guttun.","observation":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","twist":"B fragt später, ob A eher Verständnis oder Rat möchte.","lead":8,"other":1},{"id":"gb98-attentive-02","domain":"attentive","pivot":"attentive","topic":"Aufmerksames Hinwenden","key":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","section":"4.4.3","line":"A: Ich habe einen neuen Gedanken für unser Projekt. B dreht sich zu A.","reply":"B: Erzähl mir, wie du darauf kommst.","observation":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","twist":"A fühlt sich ernst genommen, auch ohne sofortige Zustimmung.","lead":9,"other":2},{"id":"gb98-attentive-03","domain":"attentive","pivot":"boundary","topic":"Aufmerksames Hinwenden","key":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","section":"4.4.3","line":"A: Meine Mutter hat angerufen. B fragt ruhig: „Wie geht es dir damit?“","reply":"A: Das hat mich heute beschäftigt.","observation":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","twist":"B bemerkt, dass A eine Pause braucht, und wartet.","lead":10,"other":3},{"id":"gb98-attentive-04","domain":"attentive","pivot":"attentive","topic":"Aufmerksames Hinwenden","key":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","section":"4.4.3","line":"A: Ich würde gern wieder zeichnen. B sagt: „Was reizt dich daran?“","reply":"A: Das Gefühl, etwas Eigenes zu schaffen.","observation":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","twist":"B erkundet, wie A Raum dafür finden kann.","lead":11,"other":4},{"id":"gb98-attentive-05","domain":"attentive","pivot":"attentive","topic":"Aufmerksames Hinwenden","key":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","section":"4.4.3","line":"A: Ich war bei der Präsentation unsicher. B: „An welcher Stelle wurde es schwierig?“","reply":"A: Vor allem bei den Fragen.","observation":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","twist":"B benennt konkrete Unterstützung, falls A sie möchte.","lead":0,"other":5},{"id":"gb98-enthusiastic-01","domain":"enthusiastic","pivot":"boundary","topic":"Begeistertes Hinwenden","key":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","section":"4.4.4","line":"A: Ich habe das Stipendium bekommen! B springt auf: „Wie großartig!“","reply":"A: Ich kann es selbst kaum glauben!","observation":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","twist":"A freut sich, bittet aber nach dem Jubel um einen ruhigen Moment.","lead":1,"other":6},{"id":"gb98-enthusiastic-02","domain":"enthusiastic","pivot":"boundary","topic":"Begeistertes Hinwenden","key":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","section":"4.4.4","line":"A: Wir haben endlich Urlaub! B strahlt: „Lass uns die Karte ausbreiten!“","reply":"A: Ich möchte erst einmal ausschlafen.","observation":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","twist":"Beide finden später einen passenden Rhythmus.","lead":2,"other":7},{"id":"gb98-enthusiastic-03","domain":"enthusiastic","pivot":"boundary","topic":"Begeistertes Hinwenden","key":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","section":"4.4.4","line":"A: Mein Bild hängt im Café. B ruft begeistert: „Das müssen wir feiern!“","reply":"A: Das bedeutet mir sehr viel.","observation":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","twist":"A gesteht, vor so viel Aufmerksamkeit auch etwas scheu zu sein.","lead":3,"other":8},{"id":"gb98-enthusiastic-04","domain":"enthusiastic","pivot":"attentive","topic":"Begeistertes Hinwenden","key":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","section":"4.4.4","line":"A: Die Prüfung ist bestanden. B klatscht begeistert und umarmt A erst nach einer Frage.","reply":"A: Ja, komm her!","observation":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","twist":"B fragt danach, ob A erzählen möchte, wie es gelaufen ist.","lead":4,"other":9},{"id":"gb98-enthusiastic-05","domain":"enthusiastic","pivot":"playful_response","topic":"Begeistertes Hinwenden","key":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","section":"4.4.4","line":"A: Der Garten trägt die ersten Tomaten! B jubelt: „Unsere erste Ernte!“","reply":"A: Du freust dich mehr als ich.","observation":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","twist":"Beide lachen und planen ein kleines gemeinsames Abendessen.","lead":5,"other":10},{"id":"gb98-playful_response-01","domain":"playful_response","pivot":"boundary","topic":"Spielerische Erwiderung","key":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","section":"4.4.5","line":"A schiebt B einen Papierball zu; B spielt ihn grinsend zurück.","reply":"A: Treffer!","observation":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","twist":"B bittet nach zwei Runden, das Spiel zu beenden.","lead":6,"other":11},{"id":"gb98-playful_response-02","domain":"playful_response","pivot":"playful_response","topic":"Spielerische Erwiderung","key":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","section":"4.4.5","line":"A tippt mit dem Zeh gegen Bs Schuh; B antwortet mit einem spielerischen Fußtippen.","reply":"A: Unsere geheime Begrüßung!","observation":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","twist":"Beide lachen und kehren dann zum Gespräch zurück.","lead":7,"other":0},{"id":"gb98-playful_response-03","domain":"playful_response","pivot":"playful_response","topic":"Spielerische Erwiderung","key":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","section":"4.4.5","line":"A macht eine kleine Verbeugung beim Tischdecken; B verbeugt sich übertrieben zurück.","reply":"A: Zu Diensten!","observation":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","twist":"B erzählt, dass dieses Ritual beide entlastet.","lead":8,"other":1},{"id":"gb98-playful_response-04","domain":"playful_response","pivot":"boundary","topic":"Spielerische Erwiderung","key":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","section":"4.4.5","line":"A bietet eine Hand für eine improvisierte Drehung an; B nimmt sie lachend.","reply":"A: Nur eine Runde!","observation":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","twist":"B sagt, in anderen Momenten sei Tanzen gerade nicht passend.","lead":9,"other":2},{"id":"gb98-playful_response-05","domain":"playful_response","pivot":"comment_high","topic":"Spielerische Erwiderung","key":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","section":"4.4.5","line":"A hebt wie beim Fechten einen Kochlöffel; B antwortet grinsend mit einer Salatgabel.","reply":"A: Friedensvertrag!","observation":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","twist":"Beide legen das Spiel sofort ab, als es ernst wird.","lead":10,"other":3},{"id":"gb98-against_contempt-01","domain":"against_contempt","pivot":"against_contempt","topic":"Hinwenden gegen die Person: Verachtung","key":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","section":"4.5.1","line":"A: Magst du meinen Entwurf sehen? B: „Dafür müsste ich mein Niveau senken.“","reply":"A: Dann lieber nicht.","observation":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","twist":"B berichtet, sich selbst zuvor von A abgewertet gefühlt zu haben.","lead":11,"other":4},{"id":"gb98-against_contempt-02","domain":"against_contempt","pivot":"against_contempt","topic":"Hinwenden gegen die Person: Verachtung","key":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","section":"4.5.1","line":"A: Wie war dein Tag? B: „Du würdest das sowieso nicht verstehen.“","reply":"A: Das tut weh.","observation":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","twist":"A schildert, dass dieser Ton häufiger geworden sei.","lead":0,"other":5},{"id":"gb98-against_contempt-03","domain":"against_contempt","pivot":"against_criticism","topic":"Hinwenden gegen die Person: Verachtung","key":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","section":"4.5.1","line":"A: Wollen wir über die Reise reden? B: „Mit deinem Organisationstalent?“","reply":"A: Sag doch konkret, was dir fehlt.","observation":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","twist":"B findet nach einer Pause eine sachliche Sorge.","lead":1,"other":6},{"id":"gb98-against_contempt-04","domain":"against_contempt","pivot":"attentive","topic":"Hinwenden gegen die Person: Verachtung","key":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","section":"4.5.1","line":"A: Ich habe den Kurs abgeschlossen. B: „Na, endlich mal etwas Einfaches geschafft.“","reply":"A: Ich hatte auf Freude gehofft.","observation":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","twist":"B erkennt die Verletzung und entschuldigt sich ausdrücklich.","lead":2,"other":7},{"id":"gb98-against_contempt-05","domain":"against_contempt","pivot":"boundary","topic":"Hinwenden gegen die Person: Verachtung","key":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","section":"4.5.1","line":"A: Mein Gefühl war anders. B: „Wie überraschend, du wieder mit deinen großen Gefühlen.“","reply":"A: So mag ich nicht weiterreden.","observation":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","twist":"A setzt eine Gesprächsgrenze.","lead":3,"other":8},{"id":"gb98-against_belligerence-01","domain":"against_belligerence","pivot":"against_belligerence","topic":"Hinwenden als Kampfansage","key":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","section":"4.5.2","line":"A: Können wir uns kurz setzen? B: „Na los, versuch mich doch zu überzeugen!“","reply":"A: Ich möchte keinen Wettkampf.","observation":"B antwortet auf Kontakt mit offensiver Provokation.","twist":"B räumt später ein, sich innerlich angegriffen zu fühlen.","lead":4,"other":9},{"id":"gb98-against_belligerence-02","domain":"against_belligerence","pivot":"boundary","topic":"Hinwenden als Kampfansage","key":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","section":"4.5.2","line":"A: Mir ist etwas wichtig. B: „Dann kämpf dafür, wenn du dich traust.“","reply":"A: So möchte ich nicht beginnen.","observation":"B antwortet auf Kontakt mit offensiver Provokation.","twist":"A berichtet, solche Aufforderungen machten ihm Angst.","lead":5,"other":10},{"id":"gb98-against_belligerence-03","domain":"against_belligerence","pivot":"attentive","topic":"Hinwenden als Kampfansage","key":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","section":"4.5.2","line":"A: Darf ich dir eine Idee zeigen? B: „Ich zerlege sie dir sofort.“","reply":"A: Es war ein Angebot, kein Test.","observation":"B antwortet auf Kontakt mit offensiver Provokation.","twist":"B gelingt es, eine konkrete Rückfrage zu stellen.","lead":6,"other":11},{"id":"gb98-against_belligerence-04","domain":"against_belligerence","pivot":"against_defensiveness","topic":"Hinwenden als Kampfansage","key":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","section":"4.5.2","line":"A: Wir müssen über das Geld reden. B: „Ich warte auf deinen nächsten Angriff!“","reply":"A: Es geht mir um eine Rechnung.","observation":"B antwortet auf Kontakt mit offensiver Provokation.","twist":"Beide erkennen ein altes Verteidigungsmuster.","lead":7,"other":0},{"id":"gb98-against_belligerence-05","domain":"against_belligerence","pivot":"against_belligerence","topic":"Hinwenden als Kampfansage","key":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","section":"4.5.2","line":"A: Kannst du mir zuhören? B: „Nur wenn du diesmal die Wahrheit erträgst!“","reply":"A: Ich brauche einen respektvollen Ton.","observation":"B antwortet auf Kontakt mit offensiver Provokation.","twist":"B gibt zu, vor dem Gespräch nervös gewesen zu sein.","lead":8,"other":1},{"id":"gb98-against_domineering-01","domain":"against_domineering","pivot":"against_domineering","topic":"Hinwenden als Kontrolle","key":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","section":"4.5.3","line":"A: Wollen wir den Sonntag planen? B: „Du gehst dahin, wo ich entscheide.“","reply":"A: Ich möchte mitentscheiden.","observation":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","twist":"A berichtet, allein Besuche nicht frei vereinbaren zu dürfen.","lead":9,"other":2},{"id":"gb98-against_domineering-02","domain":"against_domineering","pivot":"against_domineering","topic":"Hinwenden als Kontrolle","key":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","section":"4.5.3","line":"A: Ich würde gern mit Freunden essen. B: „Erst zeigst du mir deine Nachrichten.“","reply":"A: Das fühlt sich wie eine Kontrolle an.","observation":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","twist":"A beschreibt Angst vor einer negativen Reaktion.","lead":10,"other":3},{"id":"gb98-against_domineering-03","domain":"against_domineering","pivot":"boundary","topic":"Hinwenden als Kontrolle","key":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","section":"4.5.3","line":"A: Ich bin heute erschöpft. B: „Du sitzt jetzt hier und hörst mir zu!“","reply":"A: Ich brauche eine Pause.","observation":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","twist":"B weigert sich zunächst, eine Pause zuzulassen.","lead":11,"other":4},{"id":"gb98-against_domineering-04","domain":"against_domineering","pivot":"against_domineering","topic":"Hinwenden als Kontrolle","key":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","section":"4.5.3","line":"A: Können wir das Haushaltsbudget teilen? B: „Nur ich kontrolliere das Konto.“","reply":"A: Ich brauche Übersicht über unser Geld.","observation":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","twist":"A berichtet, keinen freien Zugriff auf eigenes Geld zu haben.","lead":0,"other":5},{"id":"gb98-against_domineering-05","domain":"against_domineering","pivot":"against_domineering","topic":"Hinwenden als Kontrolle","key":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","section":"4.5.3","line":"A: Darf ich meinen Bruder besuchen? B: „Ich habe dazu Nein gesagt.“","reply":"A: Ich möchte frei entscheiden können.","observation":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","twist":"A benennt, dass ähnliche Verbote schon länger vorkommen.","lead":1,"other":6},{"id":"gb98-against_criticism-01","domain":"against_criticism","pivot":"comment_low","topic":"Hinwenden als Charakterkritik","key":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","section":"4.5.4","line":"A: Sollen wir die Rechnung ansehen? B: „Du bist einfach unfähig mit Geld.“","reply":"A: Sag mir, welche Buchung du meinst.","observation":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","twist":"B nennt später einen konkreten vergessenen Betrag.","lead":2,"other":7},{"id":"gb98-against_criticism-02","domain":"against_criticism","pivot":"against_criticism","topic":"Hinwenden als Charakterkritik","key":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","section":"4.5.4","line":"A: Ich wollte mich fürs Kochen bedanken. B: „Du bist ohnehin immer egoistisch.“","reply":"A: Das passt gerade nicht zu meiner Frage.","observation":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","twist":"A berichtet, sich häufig global beurteilt zu fühlen.","lead":3,"other":8},{"id":"gb98-against_criticism-03","domain":"against_criticism","pivot":"comment_low","topic":"Hinwenden als Charakterkritik","key":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","section":"4.5.4","line":"A: Kommen wir heute zur Veranstaltung? B: „Auf dich kann man nie zählen.“","reply":"A: Ich war gestern zu spät, ja.","observation":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","twist":"B kann schließlich den tatsächlichen Ärger benennen.","lead":4,"other":9},{"id":"gb98-against_criticism-04","domain":"against_criticism","pivot":"against_defensiveness","topic":"Hinwenden als Charakterkritik","key":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","section":"4.5.4","line":"A: Ich habe die Kinder abgeholt. B: „Du bist grundsätzlich unorganisiert.“","reply":"A: Wir können über die Abholung reden.","observation":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","twist":"B erinnert sich, selbst nicht klar informiert zu haben.","lead":5,"other":10},{"id":"gb98-against_criticism-05","domain":"against_criticism","pivot":"comment_high","topic":"Hinwenden als Charakterkritik","key":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","section":"4.5.4","line":"A: Magst du die neue Lampe? B: „Dein Geschmack ist immer schlimm.“","reply":"A: Es wäre okay, sie nicht zu mögen.","observation":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","twist":"B formuliert eine konkrete Präferenz ohne Herabsetzung.","lead":6,"other":11},{"id":"gb98-against_defensiveness-01","domain":"against_defensiveness","pivot":"against_defensiveness","topic":"Hinwenden als Abwehr","key":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","section":"4.5.5","line":"A: Die Post liegt noch hier. B: „Du hältst mich wohl wieder für faul!“","reply":"A: Ich wollte nur nach dem Brief fragen.","observation":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","twist":"B sagt, sich seit einem Streit leicht kritisiert zu fühlen.","lead":7,"other":0},{"id":"gb98-against_defensiveness-02","domain":"against_defensiveness","pivot":"away_preoccupied","topic":"Hinwenden als Abwehr","key":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","section":"4.5.5","line":"A: Hast du heute Zeit für mich? B: „Ich kann auch nicht alles machen!“","reply":"A: Ich wollte zehn Minuten mit dir reden.","observation":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","twist":"B ist überlastet und versteht die Bitte erst später.","lead":8,"other":1},{"id":"gb98-against_defensiveness-03","domain":"against_defensiveness","pivot":"attentive","topic":"Hinwenden als Abwehr","key":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","section":"4.5.5","line":"A: Die Pflanze sieht trocken aus. B: „Jetzt bin ich wieder an allem schuld!“","reply":"A: Wir können sie gemeinsam gießen.","observation":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","twist":"B entschuldigt sich für die vorschnelle Unterstellung.","lead":9,"other":2},{"id":"gb98-against_defensiveness-04","domain":"against_defensiveness","pivot":"against_defensiveness","topic":"Hinwenden als Abwehr","key":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","section":"4.5.5","line":"A: Kommst du zum Essen? B: „Muss ich schon wieder alles richtig machen?“","reply":"A: Nein, ich wollte dich nur dabeihaben.","observation":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","twist":"B berichtet, häufig auf mögliche Vorwürfe zu achten.","lead":10,"other":3},{"id":"gb98-against_defensiveness-05","domain":"against_defensiveness","pivot":"attentive","topic":"Hinwenden als Abwehr","key":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","section":"4.5.5","line":"A: Ich vermisse unsere Spaziergänge. B: „Also bin ich jetzt der schlechte Partner?“","reply":"A: Es ist eine Sehnsucht, kein Urteil.","observation":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","twist":"B kann nach dem Zuhören As Wunsch besser verstehen.","lead":11,"other":4},{"id":"gb98-away_preoccupied-01","domain":"away_preoccupied","pivot":"away_preoccupied","topic":"Abwesend durch Beschäftigung","key":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","section":"4.6.1","line":"A: Schau mal diese Zeichnung! B arbeitet mit Kopfhörern weiter.","reply":"A: Ich weiß nicht, ob du mich gehört hast.","observation":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","twist":"B erklärt, eine wichtige Deadline gehabt zu haben.","lead":0,"other":5},{"id":"gb98-away_preoccupied-02","domain":"away_preoccupied","pivot":"away_preoccupied","topic":"Abwesend durch Beschäftigung","key":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","section":"4.6.1","line":"A: Ich bin von der Arbeit zurück. B vertieft sich ins Reparieren.","reply":"A: Ich hätte gern kurz Hallo gesagt.","observation":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","twist":"B bemerkt das verpasste Signal erst später.","lead":1,"other":6},{"id":"gb98-away_preoccupied-03","domain":"away_preoccupied","pivot":"low_energy","topic":"Abwesend durch Beschäftigung","key":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","section":"4.6.1","line":"A zeigt B das neue Rezept, aber B telefoniert konzentriert weiter.","reply":"A: Ich frage später noch einmal.","observation":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","twist":"B bedankt sich für das spätere Wiederanknüpfen.","lead":2,"other":7},{"id":"gb98-away_preoccupied-04","domain":"away_preoccupied","pivot":"attentive","topic":"Abwesend durch Beschäftigung","key":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","section":"4.6.1","line":"A: Mein Tag war merkwürdig. B liest mit voller Konzentration den Vertrag.","reply":"A: Wann hättest du ein paar Minuten?","observation":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","twist":"B nennt von sich aus einen konkreten Zeitpunkt.","lead":3,"other":8},{"id":"gb98-away_preoccupied-05","domain":"away_preoccupied","pivot":"attentive","topic":"Abwesend durch Beschäftigung","key":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","section":"4.6.1","line":"A: Magst du mit mir Musik hören? B hört gerade ein Webinar mit.","reply":"A: Ich sehe, du bist beschäftigt.","observation":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","twist":"B erklärt den Kontext und schlägt später eine Alternative vor.","lead":4,"other":9},{"id":"gb98-away_interrupt-01","domain":"away_interrupt","pivot":"attentive","topic":"Unterbrechendes Abwenden","key":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","section":"4.6.2","line":"A: Ich habe heute etwas erlebt … B: „Hast du die Überweisung gemacht?“","reply":"A: Meine Geschichte ist gerade untergegangen.","observation":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","twist":"B merkt, dass die eigene Frage bis morgen warten kann.","lead":5,"other":10},{"id":"gb98-away_interrupt-02","domain":"away_interrupt","pivot":"attentive","topic":"Unterbrechendes Abwenden","key":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","section":"4.6.2","line":"A: Magst du hören, was mich beschäftigt? B: „Wir müssen erst den Müll rausbringen.“","reply":"A: Ich wollte mich dir anvertrauen.","observation":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","twist":"B schlägt vor, den Müll danach zu erledigen.","lead":6,"other":11},{"id":"gb98-away_interrupt-03","domain":"away_interrupt","pivot":"attentive","topic":"Unterbrechendes Abwenden","key":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","section":"4.6.2","line":"A: Unsere Reise hat mich … B: „Das Handy muss geladen werden!“","reply":"A: Ich habe den Faden verloren.","observation":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","twist":"B entschuldigt sich und fragt nach dem Beginn.","lead":7,"other":0},{"id":"gb98-away_interrupt-04","domain":"away_interrupt","pivot":"attentive","topic":"Unterbrechendes Abwenden","key":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","section":"4.6.2","line":"A: Ich wünsche mir ein … B: „Stell bitte den Timer!“","reply":"A: Ich möchte ausreden.","observation":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","twist":"B erkennt, dass der eigene Impuls nichts mit As Thema zu tun hatte.","lead":8,"other":1},{"id":"gb98-away_interrupt-05","domain":"away_interrupt","pivot":"attentive","topic":"Unterbrechendes Abwenden","key":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","section":"4.6.2","line":"A: Gestern war ich traurig, weil … B: „Meine Kollegin hat übrigens gekündigt.“","reply":"A: Du hast mich unterbrochen.","observation":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","twist":"B fasst As Aussage anschließend zusammen.","lead":9,"other":2},{"id":"gb98-away_disregard-01","domain":"away_disregard","pivot":"away_disregard","topic":"Ignorierendes Abwenden","key":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","section":"4.6.3","line":"A sitzt neben B und sagt deutlich: „Ich brauche kurz Kontakt.“ B reagiert nicht.","reply":"A: Ich fühle mich übergangen.","observation":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","twist":"B berichtet, wegen eines Streits absichtlich nicht antworten gewollt zu haben.","lead":10,"other":3},{"id":"gb98-away_disregard-02","domain":"away_disregard","pivot":"away_preoccupied","topic":"Ignorierendes Abwenden","key":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","section":"4.6.3","line":"A stellt B eine direkte Frage beim Frühstück. B blickt auf die Uhr und schweigt.","reply":"A: Ich habe keine Reaktion bekommen.","observation":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","twist":"B erklärt später, die Frage sei im Lärm untergegangen.","lead":11,"other":4},{"id":"gb98-away_disregard-03","domain":"away_disregard","pivot":"boundary","topic":"Ignorierendes Abwenden","key":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","section":"4.6.3","line":"A bittet um Rückmeldung zu einem Brief. B hört zu und wechselt wortlos das Zimmer.","reply":"A: Ich weiß nicht, woran ich bin.","observation":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","twist":"B gibt an, Angst vor einer weiteren Diskussion gehabt zu haben.","lead":0,"other":5},{"id":"gb98-away_disregard-04","domain":"away_disregard","pivot":"boundary","topic":"Ignorierendes Abwenden","key":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","section":"4.6.3","line":"A: Magst du mir helfen, das Foto zu wählen? B sieht A an und setzt Kopfhörer auf.","reply":"A: Ich fühle mich weggeschoben.","observation":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","twist":"B kann danach erklären, welche Grenze gerade nötig war.","lead":1,"other":6},{"id":"gb98-away_disregard-05","domain":"away_disregard","pivot":"against_defensiveness","topic":"Ignorierendes Abwenden","key":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","section":"4.6.3","line":"A zeigt B den Terminplan; B schaut darauf, wendet sich aber ohne Antwort ab.","reply":"A: Hast du ihn gesehen?","observation":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","twist":"B nennt später die Sorge, wieder eine Aufgabe zugewiesen zu bekommen.","lead":2,"other":7},{"id":"gb98-nonbid-01","domain":"nonbid","pivot":"attentive","topic":"Kein an Partner gerichtetes Bid","key":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","section":"4.2.3","line":"A murmelt beim Kochen die Zutatenliste für sich selbst.","reply":"B steht in der Tür und hört zufällig mit.","observation":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","twist":"B fragt, ob A Unterstützung möchte; erst jetzt beginnt Kontakt.","lead":3,"other":8},{"id":"gb98-nonbid-02","domain":"nonbid","pivot":"comment_low","topic":"Kein an Partner gerichtetes Bid","key":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","section":"4.2.3","line":"A telefoniert mit einer Kollegin über einen Termin.","reply":"B hört die Hälfte davon aus dem Nachbarzimmer.","observation":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","twist":"A beendet das Telefonat und richtet sich danach an B.","lead":4,"other":9},{"id":"gb98-nonbid-03","domain":"nonbid","pivot":"nonbid","topic":"Kein an Partner gerichtetes Bid","key":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","section":"4.2.3","line":"A schaut nur kurz zur Tür und zurück auf den Bildschirm.","reply":"B sitzt nebenan und liest.","observation":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","twist":"A erklärt, bloß ein Geräusch überprüft zu haben.","lead":5,"other":10},{"id":"gb98-nonbid-04","domain":"nonbid","pivot":"comment_low","topic":"Kein an Partner gerichtetes Bid","key":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","section":"4.2.3","line":"A beginnt einen Satz und bricht ihn sofort ohne erkennbare Adressierung ab.","reply":"B sagt nichts dazu.","observation":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","twist":"A formuliert später eine klare Einladung.","lead":6,"other":11},{"id":"gb98-nonbid-05","domain":"nonbid","pivot":"nonbid","topic":"Kein an Partner gerichtetes Bid","key":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","section":"4.2.3","line":"A schaut beiläufig auf die Uhr und seufzt einmal.","reply":"B legt den Kopf schief.","observation":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","twist":"A sagt, das habe nichts mit B zu tun gehabt.","lead":7,"other":0},{"id":"gb98-boundary-01","domain":"boundary","pivot":"boundary","topic":"Freiwillige Grenze statt Zurückweisung","key":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","section":"4.2 / 4.4–4.6; professionelle Ergänzung","line":"A: Magst du dich an mich kuscheln? B: „Heute möchte ich keine Berührung, aber reden.“","reply":"A: Danke, dass du es sagst.","observation":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","twist":"A respektiert die Grenze und beide sprechen weiter.","lead":8,"other":1},{"id":"gb98-boundary-02","domain":"boundary","pivot":"boundary","topic":"Freiwillige Grenze statt Zurückweisung","key":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","section":"4.2 / 4.4–4.6; professionelle Ergänzung","line":"A: Können wir jetzt über gestern sprechen? B: „Ich brauche eine Pause bis morgen früh.“","reply":"A: Dann vereinbaren wir eine Uhrzeit.","observation":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","twist":"B hält die vereinbarte Rückkehr zuverlässig ein.","lead":9,"other":2},{"id":"gb98-boundary-03","domain":"boundary","pivot":"boundary","topic":"Freiwillige Grenze statt Zurückweisung","key":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","section":"4.2 / 4.4–4.6; professionelle Ergänzung","line":"A: Zeigst du mir dein Tagebuch? B: „Das bleibt privat, aber ich erzähle dir gern, wie es mir geht.“","reply":"A: Ich wollte dir nicht zu nahe treten.","observation":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","twist":"B fühlt sich respektiert und öffnet sich freiwillig.","lead":10,"other":3},{"id":"gb98-boundary-04","domain":"boundary","pivot":"boundary","topic":"Freiwillige Grenze statt Zurückweisung","key":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","section":"4.2 / 4.4–4.6; professionelle Ergänzung","line":"A: Magst du am Wochenende mitkommen? B: „Nein, ich brauche Zeit allein.“","reply":"A: Dann planen wir etwas anderes zusammen.","observation":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","twist":"Beide finden Raum für Autonomie und Verbindung.","lead":11,"other":4},{"id":"gb98-boundary-05","domain":"boundary","pivot":"against_domineering","topic":"Freiwillige Grenze statt Zurückweisung","key":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","section":"4.2 / 4.4–4.6; professionelle Ergänzung","line":"A: Ich will jetzt dein Passwort sehen. B: „Nein. Ich rede über Vertrauen, nicht über Überwachung.“","reply":"A: Ich bin verunsichert und brauche andere Sicherheit.","observation":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","twist":"B beschreibt, sich bei solchen Forderungen zunehmend kontrolliert zu fühlen.","lead":0,"other":5}],"knowledge":[{"id":"gb98-k-silent-1","domain":"silent","type":"Einordnung","question":"Was unterscheidet „Stilles Kontaktangebot“ in der beobachteten Interaktion?","correct":"Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","alternatives":["Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen."],"why":"Kapitel 4.3.1: Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","section":"4.3.1"},{"id":"gb98-k-silent-2","domain":"silent","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Stilles Kontaktangebot“?","correct":"A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","alternatives":["A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot."],"why":"Der beobachtbare Hinweis ist: A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","section":"4.3.1"},{"id":"gb98-k-silent-3","domain":"silent","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Stilles Kontaktangebot“ am ehesten?","correct":"Haben Sie bemerkt, dass gerade ohne Worte Kontakt angeboten wurde?","alternatives":["War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","Wurde hier überhaupt ein Kontaktversuch an B gemacht?"],"why":"Ohne Gedankenlesen nachfragen: Haben Sie bemerkt, dass gerade ohne Worte Kontakt angeboten wurde?","section":"4.3.1"},{"id":"gb98-k-silent-4","domain":"silent","type":"Transfer","question":"Wie würdest du bei „Stilles Kontaktangebot“ zunächst professionell weiterarbeiten?","correct":"Ein sichtbares stilles Angebot beschreiben, B nach eigener Wahrnehmung fragen.","alternatives":["Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten.","Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen.","Nicht jedes Verhalten als Beziehungssignal werten; die tatsächliche Adressierung klären."],"why":"Vorrangiger Arbeitsschritt: Ein sichtbares stilles Angebot beschreiben, B nach eigener Wahrnehmung fragen. Grenzen: Ein flüchtiger Blick ohne Kontaktabsicht ist nicht zwingend ein Bid.","section":"4.3.1"},{"id":"gb98-k-comment_low-1","domain":"comment_low","type":"Einordnung","question":"Was unterscheidet „Sachlicher Kommentar“ in der beobachteten Interaktion?","correct":"Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","alternatives":["Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen."],"why":"Kapitel 4.3.2: Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","section":"4.3.2"},{"id":"gb98-k-comment_low-2","domain":"comment_low","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Sachlicher Kommentar“?","correct":"A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","alternatives":["A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot."],"why":"Der beobachtbare Hinweis ist: A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","section":"4.3.2"},{"id":"gb98-k-comment_low-3","domain":"comment_low","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Sachlicher Kommentar“ am ehesten?","correct":"War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","alternatives":["Was war Ihnen daran persönlich wichtig?","Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","Wurde hier überhaupt ein Kontaktversuch an B gemacht?"],"why":"Ohne Gedankenlesen nachfragen: War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","section":"4.3.2"},{"id":"gb98-k-comment_low-4","domain":"comment_low","type":"Transfer","question":"Wie würdest du bei „Sachlicher Kommentar“ zunächst professionell weiterarbeiten?","correct":"Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten.","alternatives":["Persönlichen Gehalt aufnehmen und neugierig weiterfragen.","Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation.","Nicht jedes Verhalten als Beziehungssignal werten; die tatsächliche Adressierung klären."],"why":"Vorrangiger Arbeitsschritt: Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten. Grenzen: Nicht jeder gesprochene Satz ist eine Bitte um tiefes Gespräch.","section":"4.3.2"},{"id":"gb98-k-comment_high-1","domain":"comment_high","type":"Einordnung","question":"Was unterscheidet „Persönlicher Kommentar“ in der beobachteten Interaktion?","correct":"Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","alternatives":["Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen."],"why":"Kapitel 4.3.2: Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","section":"4.3.2"},{"id":"gb98-k-comment_high-2","domain":"comment_high","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Persönlicher Kommentar“?","correct":"A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","alternatives":["A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung."],"why":"Der beobachtbare Hinweis ist: A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","section":"4.3.2"},{"id":"gb98-k-comment_high-3","domain":"comment_high","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Persönlicher Kommentar“ am ehesten?","correct":"Was war Ihnen daran persönlich wichtig?","alternatives":["War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","Welche eigene Bedeutung könnte diese Frage für B haben?","Was genau macht das Zuhören für A hier spürbar?"],"why":"Ohne Gedankenlesen nachfragen: Was war Ihnen daran persönlich wichtig?","section":"4.3.2"},{"id":"gb98-k-comment_high-4","domain":"comment_high","type":"Transfer","question":"Wie würdest du bei „Persönlicher Kommentar“ zunächst professionell weiterarbeiten?","correct":"Persönlichen Gehalt aufnehmen und neugierig weiterfragen.","alternatives":["Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten.","Die subjektive Antwort neugierig aufnehmen, statt nur Fakten auszutauschen.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen."],"why":"Vorrangiger Arbeitsschritt: Persönlichen Gehalt aufnehmen und neugierig weiterfragen. Grenzen: Hohes Level meint Inhalt, nicht unbedingt Lautstärke oder Aufregung.","section":"4.3.2"},{"id":"gb98-k-question_low-1","domain":"question_low","type":"Einordnung","question":"Was unterscheidet „Informationsfrage“ in der beobachteten Interaktion?","correct":"Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","alternatives":["A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering."],"why":"Kapitel 4.3.3: Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","section":"4.3.3"},{"id":"gb98-k-question_low-2","domain":"question_low","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Informationsfrage“?","correct":"A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","alternatives":["Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp."],"why":"Der beobachtbare Hinweis ist: A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","section":"4.3.3"},{"id":"gb98-k-question_low-3","domain":"question_low","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Informationsfrage“ am ehesten?","correct":"Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","alternatives":["Welche eigene Bedeutung könnte diese Frage für B haben?","War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?"],"why":"Ohne Gedankenlesen nachfragen: Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","section":"4.3.3"},{"id":"gb98-k-question_low-4","domain":"question_low","type":"Transfer","question":"Wie würdest du bei „Informationsfrage“ zunächst professionell weiterarbeiten?","correct":"Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation.","alternatives":["Die subjektive Antwort neugierig aufnehmen, statt nur Fakten auszutauschen.","Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten.","Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen."],"why":"Vorrangiger Arbeitsschritt: Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation. Grenzen: Eine Frage nach Fakten ist nicht automatisch ein Vorwurf oder Intimitätsangebot.","section":"4.3.3"},{"id":"gb98-k-question_high-1","domain":"question_high","type":"Einordnung","question":"Was unterscheidet „Frage nach Gedanken oder Gefühlen“ in der beobachteten Interaktion?","correct":"A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","alternatives":["Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen."],"why":"Kapitel 4.3.3: A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben.","section":"4.3.3"},{"id":"gb98-k-question_high-2","domain":"question_high","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Frage nach Gedanken oder Gefühlen“?","correct":"Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","alternatives":["A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung."],"why":"Der beobachtbare Hinweis ist: Die Frage zielt auf subjektives Denken, Empfinden oder Wollen.","section":"4.3.3"},{"id":"gb98-k-question_high-3","domain":"question_high","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Frage nach Gedanken oder Gefühlen“ am ehesten?","correct":"Welche eigene Bedeutung könnte diese Frage für B haben?","alternatives":["Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","Was war Ihnen daran persönlich wichtig?","Was genau macht das Zuhören für A hier spürbar?"],"why":"Ohne Gedankenlesen nachfragen: Welche eigene Bedeutung könnte diese Frage für B haben?","section":"4.3.3"},{"id":"gb98-k-question_high-4","domain":"question_high","type":"Transfer","question":"Wie würdest du bei „Frage nach Gedanken oder Gefühlen“ zunächst professionell weiterarbeiten?","correct":"Die subjektive Antwort neugierig aufnehmen, statt nur Fakten auszutauschen.","alternatives":["Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation.","Persönlichen Gehalt aufnehmen und neugierig weiterfragen.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen."],"why":"Vorrangiger Arbeitsschritt: Die subjektive Antwort neugierig aufnehmen, statt nur Fakten auszutauschen. Grenzen: Eine kurze Frage kann persönlich sein, auch wenn sie sachlich klingt.","section":"4.3.3"},{"id":"gb98-k-playful_bid-1","domain":"playful_bid","type":"Einordnung","question":"Was unterscheidet „Spielerisches Kontaktangebot“ in der beobachteten Interaktion?","correct":"Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","alternatives":["Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot."],"why":"Kapitel 4.3.4: Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","section":"4.3.4"},{"id":"gb98-k-playful_bid-2","domain":"playful_bid","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Spielerisches Kontaktangebot“?","correct":"A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","alternatives":["A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","B antwortet auf Kontakt mit offensiver Provokation.","B erwidert As spielerische Bewegung freiwillig und beide haben Spaß."],"why":"Der beobachtbare Hinweis ist: A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","section":"4.3.4"},{"id":"gb98-k-playful_bid-3","domain":"playful_bid","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Spielerisches Kontaktangebot“ am ehesten?","correct":"War das Spiel für beide lustig und freiwillig?","alternatives":["Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","Wird hier gerade Verbindung gesucht oder eine Auseinandersetzung angeheizt?","Wie zeigen beide, dass das Spiel für sie willkommen ist?"],"why":"Ohne Gedankenlesen nachfragen: War das Spiel für beide lustig und freiwillig?","section":"4.3.4"},{"id":"gb98-k-playful_bid-4","domain":"playful_bid","type":"Transfer","question":"Wie würdest du bei „Spielerisches Kontaktangebot“ zunächst professionell weiterarbeiten?","correct":"Gemeinsamen Humor als Ressource würdigen, ohne Zustimmung vorauszusetzen.","alternatives":["Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation.","Den Machtkampf unterbrechen, sicheren Rahmen und Tempo vereinbaren.","Die wechselseitige Zustimmung und geteilte Freude wahrnehmen."],"why":"Vorrangiger Arbeitsschritt: Gemeinsamen Humor als Ressource würdigen, ohne Zustimmung vorauszusetzen. Grenzen: Humor mit Beschämung, Druck oder unerwünschter Berührung ist kein unproblematisches Spiel.","section":"4.3.4"},{"id":"gb98-k-negative_bid-1","domain":"negative_bid","type":"Einordnung","question":"Was unterscheidet „Negatives Kontaktangebot“ in der beobachteten Interaktion?","correct":"Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","alternatives":["Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","Eine Bemerkung, in der Gedanken, Bewertung oder Gefühle mitgeteilt werden."],"why":"Kapitel 4.3.5: Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität.","section":"4.3.5"},{"id":"gb98-k-negative_bid-2","domain":"negative_bid","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Negatives Kontaktangebot“?","correct":"A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","alternatives":["Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","A benennt eine eigene Meinung, Vorliebe oder emotionale Bedeutung."],"why":"Der beobachtbare Hinweis ist: A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B.","section":"4.3.5"},{"id":"gb98-k-negative_bid-3","domain":"negative_bid","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Negatives Kontaktangebot“ am ehesten?","correct":"Was wird hier zum Kontaktangebot, obwohl es gleichzeitig verletzt?","alternatives":["Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","Wessen Wahlfreiheit wird gerade eingeschränkt?","Was war Ihnen daran persönlich wichtig?"],"why":"Ohne Gedankenlesen nachfragen: Was wird hier zum Kontaktangebot, obwohl es gleichzeitig verletzt?","section":"4.3.5"},{"id":"gb98-k-negative_bid-4","domain":"negative_bid","type":"Transfer","question":"Wie würdest du bei „Negatives Kontaktangebot“ zunächst professionell weiterarbeiten?","correct":"Abwertung begrenzen und das mögliche Anliegen dahinter vorsichtig erfragen.","alternatives":["Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten.","Machtanspruch und Freiwilligkeit klären; bei Zwang Sicherheit priorisieren.","Persönlichen Gehalt aufnehmen und neugierig weiterfragen."],"why":"Vorrangiger Arbeitsschritt: Abwertung begrenzen und das mögliche Anliegen dahinter vorsichtig erfragen. Grenzen: Sicherheit, Einschüchterung und Machtgefälle gehen vor Kommunikationsübungen.","section":"4.3.5"},{"id":"gb98-k-rebid-1","domain":"rebid","type":"Einordnung","question":"Was unterscheidet „Erneutes gleiches Kontaktangebot“ in der beobachteten Interaktion?","correct":"Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","alternatives":["Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung.","Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab."],"why":"Kapitel 4.3.6: Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt.","section":"4.3.6"},{"id":"gb98-k-rebid-2","domain":"rebid","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Erneutes gleiches Kontaktangebot“?","correct":"A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","alternatives":["A bittet B um ein Datum, einen Ort oder eine praktische Tatsache.","B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt."],"why":"Der beobachtbare Hinweis ist: A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion.","section":"4.3.6"},{"id":"gb98-k-rebid-3","domain":"rebid","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Erneutes gleiches Kontaktangebot“ am ehesten?","correct":"Was wurde beim ersten Versuch angeboten und wie wurde darauf reagiert?","alternatives":["Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?","War die Einladung für B überhaupt wahrnehmbar?","War das ein natürlicher Abschluss oder ein abrupter Kontaktabbruch?"],"why":"Ohne Gedankenlesen nachfragen: Was wurde beim ersten Versuch angeboten und wie wurde darauf reagiert?","section":"4.3.6"},{"id":"gb98-k-rebid-4","domain":"rebid","type":"Transfer","question":"Wie würdest du bei „Erneutes gleiches Kontaktangebot“ zunächst professionell weiterarbeiten?","correct":"Erste Reaktion benennen, wiederholtes Angebot würdigen und nach Wirkung fragen.","alternatives":["Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation.","Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","Den Bruch behutsam markieren und den Grund erfragen, ohne Absicht festzulegen."],"why":"Vorrangiger Arbeitsschritt: Erste Reaktion benennen, wiederholtes Angebot würdigen und nach Wirkung fragen. Grenzen: Ein neuer Themenwechsel ist kein Rebid desselben Anliegens.","section":"4.3.6"},{"id":"gb98-k-dropout-1","domain":"dropout","type":"Einordnung","question":"Was unterscheidet „Abrupter Gesprächsabbruch“ in der beobachteten Interaktion?","correct":"Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","alternatives":["Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein."],"why":"Kapitel 4.3.7: Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab.","section":"4.3.7"},{"id":"gb98-k-dropout-2","domain":"dropout","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Abrupter Gesprächsabbruch“?","correct":"Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","alternatives":["B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion."],"why":"Der beobachtbare Hinweis ist: Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt.","section":"4.3.7"},{"id":"gb98-k-dropout-3","domain":"dropout","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Abrupter Gesprächsabbruch“ am ehesten?","correct":"War das ein natürlicher Abschluss oder ein abrupter Kontaktabbruch?","alternatives":["Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","War die Einladung für B überhaupt wahrnehmbar?","Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?"],"why":"Ohne Gedankenlesen nachfragen: War das ein natürlicher Abschluss oder ein abrupter Kontaktabbruch?","section":"4.3.7"},{"id":"gb98-k-dropout-4","domain":"dropout","type":"Transfer","question":"Wie würdest du bei „Abrupter Gesprächsabbruch“ zunächst professionell weiterarbeiten?","correct":"Den Bruch behutsam markieren und den Grund erfragen, ohne Absicht festzulegen.","alternatives":["Beobachtung benennen, Wirkung erfragen und Gründe offenlassen.","Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen."],"why":"Vorrangiger Arbeitsschritt: Den Bruch behutsam markieren und den Grund erfragen, ohne Absicht festzulegen. Grenzen: Von Drop-out nicht automatisch auf Desinteresse schließen: Überforderung und Schutz prüfen.","section":"4.3.7"},{"id":"gb98-k-passive-1","domain":"passive","type":"Einordnung","question":"Was unterscheidet „Passives Hinwenden“ in der beobachteten Interaktion?","correct":"Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","alternatives":["Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen."],"why":"Kapitel 4.4.1: Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","section":"4.4.1"},{"id":"gb98-k-passive-2","domain":"passive","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Passives Hinwenden“?","correct":"B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","alternatives":["B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung."],"why":"Der beobachtbare Hinweis ist: B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","section":"4.4.1"},{"id":"gb98-k-passive-3","domain":"passive","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Passives Hinwenden“ am ehesten?","correct":"Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","alternatives":["Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","War die Einladung für B überhaupt wahrnehmbar?","Was genau macht das Zuhören für A hier spürbar?"],"why":"Ohne Gedankenlesen nachfragen: Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","section":"4.4.1"},{"id":"gb98-k-passive-4","domain":"passive","type":"Transfer","question":"Wie würdest du bei „Passives Hinwenden“ zunächst professionell weiterarbeiten?","correct":"Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen.","alternatives":["Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen.","Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen."],"why":"Vorrangiger Arbeitsschritt: Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen. Grenzen: Wenn A die minimale Reaktion gar nicht wahrnehmen kann, passt eher Turning Away.","section":"4.4.1"},{"id":"gb98-k-low_energy-1","domain":"low_energy","type":"Einordnung","question":"Was unterscheidet „Knappes sachliches Hinwenden“ in der beobachteten Interaktion?","correct":"Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","alternatives":["Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","Die Frage verlangt primär eine sachliche Information, nicht eine persönliche Bewertung."],"why":"Kapitel 4.4.2: Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","section":"4.4.2"},{"id":"gb98-k-low_energy-2","domain":"low_energy","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Knappes sachliches Hinwenden“?","correct":"B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","alternatives":["B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","A bittet B um ein Datum, einen Ort oder eine praktische Tatsache."],"why":"Der beobachtbare Hinweis ist: B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","section":"4.4.2"},{"id":"gb98-k-low_energy-3","domain":"low_energy","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Knappes sachliches Hinwenden“ am ehesten?","correct":"Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","alternatives":["Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","Was genau macht das Zuhören für A hier spürbar?","Welche Art von Antwort war mit dieser Frage unmittelbar gefragt?"],"why":"Ohne Gedankenlesen nachfragen: Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","section":"4.4.2"},{"id":"gb98-k-low_energy-4","domain":"low_energy","type":"Transfer","question":"Wie würdest du bei „Knappes sachliches Hinwenden“ zunächst professionell weiterarbeiten?","correct":"Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen.","alternatives":["Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen.","Die Informationsfrage respektieren; keine ungefragte Tiefeninterpretation."],"why":"Vorrangiger Arbeitsschritt: Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen. Grenzen: Low Energy ist kein Zeichen mangelnder Liebe; Personen haben verschiedene Ausdrucksstile.","section":"4.4.2"},{"id":"gb98-k-attentive-1","domain":"attentive","type":"Einordnung","question":"Was unterscheidet „Aufmerksames Hinwenden“ in der beobachteten Interaktion?","correct":"Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","alternatives":["Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","A erkundet Bs Meinung, Wunsch, Geschmack oder emotionales Erleben."],"why":"Kapitel 4.4.3: Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","section":"4.4.3"},{"id":"gb98-k-attentive-2","domain":"attentive","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Aufmerksames Hinwenden“?","correct":"B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","alternatives":["B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","B antwortet lebhaft und sichtbar mit hoher Begeisterung.","Die Frage zielt auf subjektives Denken, Empfinden oder Wollen."],"why":"Der beobachtbare Hinweis ist: B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","section":"4.4.3"},{"id":"gb98-k-attentive-3","domain":"attentive","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Aufmerksames Hinwenden“ am ehesten?","correct":"Was genau macht das Zuhören für A hier spürbar?","alternatives":["Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","Wie wirkt diese Energie auf die Person, die das Angebot gemacht hat?","Welche eigene Bedeutung könnte diese Frage für B haben?"],"why":"Ohne Gedankenlesen nachfragen: Was genau macht das Zuhören für A hier spürbar?","section":"4.4.3"},{"id":"gb98-k-attentive-4","domain":"attentive","type":"Transfer","question":"Wie würdest du bei „Aufmerksames Hinwenden“ zunächst professionell weiterarbeiten?","correct":"Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen.","alternatives":["Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen.","Freude als Ressource nutzen; Intensität an gegenseitige Passung anpassen.","Die subjektive Antwort neugierig aufnehmen, statt nur Fakten auszutauschen."],"why":"Vorrangiger Arbeitsschritt: Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen. Grenzen: Aufmerksamkeit lässt sich nicht aus Blickkontakt allein ableiten.","section":"4.4.3"},{"id":"gb98-k-enthusiastic-1","domain":"enthusiastic","type":"Einordnung","question":"Was unterscheidet „Begeistertes Hinwenden“ in der beobachteten Interaktion?","correct":"Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","alternatives":["Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen.","Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering."],"why":"Kapitel 4.4.4: Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","section":"4.4.4"},{"id":"gb98-k-enthusiastic-2","domain":"enthusiastic","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Begeistertes Hinwenden“?","correct":"B antwortet lebhaft und sichtbar mit hoher Begeisterung.","alternatives":["B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung.","B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp."],"why":"Der beobachtbare Hinweis ist: B antwortet lebhaft und sichtbar mit hoher Begeisterung.","section":"4.4.4"},{"id":"gb98-k-enthusiastic-3","domain":"enthusiastic","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Begeistertes Hinwenden“ am ehesten?","correct":"Wie wirkt diese Energie auf die Person, die das Angebot gemacht hat?","alternatives":["Was genau macht das Zuhören für A hier spürbar?","Wie zeigen beide, dass das Spiel für sie willkommen ist?","Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?"],"why":"Ohne Gedankenlesen nachfragen: Wie wirkt diese Energie auf die Person, die das Angebot gemacht hat?","section":"4.4.4"},{"id":"gb98-k-enthusiastic-4","domain":"enthusiastic","type":"Transfer","question":"Wie würdest du bei „Begeistertes Hinwenden“ zunächst professionell weiterarbeiten?","correct":"Freude als Ressource nutzen; Intensität an gegenseitige Passung anpassen.","alternatives":["Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen.","Die wechselseitige Zustimmung und geteilte Freude wahrnehmen.","Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen."],"why":"Vorrangiger Arbeitsschritt: Freude als Ressource nutzen; Intensität an gegenseitige Passung anpassen. Grenzen: Viel Energie ist nicht für jede Person angenehm; Wirkung und Reizbelastung beachten.","section":"4.4.4"},{"id":"gb98-k-playful_response-1","domain":"playful_response","type":"Einordnung","question":"Was unterscheidet „Spielerische Erwiderung“ in der beobachteten Interaktion?","correct":"Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","alternatives":["Auf ein Bid folgt spürbar energiereiche, freudige Beteiligung.","Eine spielerische, von beiden als willkommen erlebte Kontaktanbahnung.","Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein."],"why":"Kapitel 4.4.5: Eine willkommen geheißene körperlich-spielerische Antwort auf ein Spielangebot.","section":"4.4.5"},{"id":"gb98-k-playful_response-2","domain":"playful_response","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Spielerische Erwiderung“?","correct":"B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","alternatives":["B antwortet lebhaft und sichtbar mit hoher Begeisterung.","A macht ein spielerisches Angebot; B hat erkennbar Freude daran.","B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später."],"why":"Der beobachtbare Hinweis ist: B erwidert As spielerische Bewegung freiwillig und beide haben Spaß.","section":"4.4.5"},{"id":"gb98-k-playful_response-3","domain":"playful_response","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Spielerische Erwiderung“ am ehesten?","correct":"Wie zeigen beide, dass das Spiel für sie willkommen ist?","alternatives":["Wie wirkt diese Energie auf die Person, die das Angebot gemacht hat?","War das Spiel für beide lustig und freiwillig?","Welche Grenze wird gesetzt, und welche Verbindung bleibt möglich?"],"why":"Ohne Gedankenlesen nachfragen: Wie zeigen beide, dass das Spiel für sie willkommen ist?","section":"4.4.5"},{"id":"gb98-k-playful_response-4","domain":"playful_response","type":"Transfer","question":"Wie würdest du bei „Spielerische Erwiderung“ zunächst professionell weiterarbeiten?","correct":"Die wechselseitige Zustimmung und geteilte Freude wahrnehmen.","alternatives":["Freude als Ressource nutzen; Intensität an gegenseitige Passung anpassen.","Gemeinsamen Humor als Ressource würdigen, ohne Zustimmung vorauszusetzen.","Das Nein als gültige Grenze anerkennen; nicht als Liebesentzug interpretieren."],"why":"Vorrangiger Arbeitsschritt: Die wechselseitige Zustimmung und geteilte Freude wahrnehmen. Grenzen: Körperliche Reaktion muss einvernehmlich sein, keine Überraschungsberührung voraussetzen.","section":"4.4.5"},{"id":"gb98-k-against_contempt-1","domain":"against_contempt","type":"Einordnung","question":"Was unterscheidet „Hinwenden gegen die Person: Verachtung“ in der beobachteten Interaktion?","correct":"Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","alternatives":["Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität."],"why":"Kapitel 4.5.1: Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","section":"4.5.1"},{"id":"gb98-k-against_contempt-2","domain":"against_contempt","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Hinwenden gegen die Person: Verachtung“?","correct":"B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","alternatives":["Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","B antwortet auf Kontakt mit offensiver Provokation.","A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B."],"why":"Der beobachtbare Hinweis ist: B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","section":"4.5.1"},{"id":"gb98-k-against_contempt-3","domain":"against_contempt","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Hinwenden gegen die Person: Verachtung“ am ehesten?","correct":"Welcher Satz verletzt gerade Würde und Gleichwertigkeit?","alternatives":["Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","Wird hier gerade Verbindung gesucht oder eine Auseinandersetzung angeheizt?","Was wird hier zum Kontaktangebot, obwohl es gleichzeitig verletzt?"],"why":"Ohne Gedankenlesen nachfragen: Welcher Satz verletzt gerade Würde und Gleichwertigkeit?","section":"4.5.1"},{"id":"gb98-k-against_contempt-4","domain":"against_contempt","type":"Transfer","question":"Wie würdest du bei „Hinwenden gegen die Person: Verachtung“ zunächst professionell weiterarbeiten?","correct":"Abwertung klar begrenzen und die zugrunde liegende Beschwerde konkretisieren.","alternatives":["Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten.","Den Machtkampf unterbrechen, sicheren Rahmen und Tempo vereinbaren.","Abwertung begrenzen und das mögliche Anliegen dahinter vorsichtig erfragen."],"why":"Vorrangiger Arbeitsschritt: Abwertung klar begrenzen und die zugrunde liegende Beschwerde konkretisieren. Grenzen: Herabsetzung nicht durch Humor oder „ehrliche Meinung“ legitimieren.","section":"4.5.1"},{"id":"gb98-k-against_belligerence-1","domain":"against_belligerence","type":"Einordnung","question":"Was unterscheidet „Hinwenden als Kampfansage“ in der beobachteten Interaktion?","correct":"Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","alternatives":["Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität."],"why":"Kapitel 4.5.2: Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","section":"4.5.2"},{"id":"gb98-k-against_belligerence-2","domain":"against_belligerence","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Hinwenden als Kampfansage“?","correct":"B antwortet auf Kontakt mit offensiver Provokation.","alternatives":["B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B."],"why":"Der beobachtbare Hinweis ist: B antwortet auf Kontakt mit offensiver Provokation.","section":"4.5.2"},{"id":"gb98-k-against_belligerence-3","domain":"against_belligerence","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Hinwenden als Kampfansage“ am ehesten?","correct":"Wird hier gerade Verbindung gesucht oder eine Auseinandersetzung angeheizt?","alternatives":["Welcher Satz verletzt gerade Würde und Gleichwertigkeit?","Wessen Wahlfreiheit wird gerade eingeschränkt?","Was wird hier zum Kontaktangebot, obwohl es gleichzeitig verletzt?"],"why":"Ohne Gedankenlesen nachfragen: Wird hier gerade Verbindung gesucht oder eine Auseinandersetzung angeheizt?","section":"4.5.2"},{"id":"gb98-k-against_belligerence-4","domain":"against_belligerence","type":"Transfer","question":"Wie würdest du bei „Hinwenden als Kampfansage“ zunächst professionell weiterarbeiten?","correct":"Den Machtkampf unterbrechen, sicheren Rahmen und Tempo vereinbaren.","alternatives":["Abwertung klar begrenzen und die zugrunde liegende Beschwerde konkretisieren.","Machtanspruch und Freiwilligkeit klären; bei Zwang Sicherheit priorisieren.","Abwertung begrenzen und das mögliche Anliegen dahinter vorsichtig erfragen."],"why":"Vorrangiger Arbeitsschritt: Den Machtkampf unterbrechen, sicheren Rahmen und Tempo vereinbaren. Grenzen: Bei Drohungen vor jeder Dialogübung gezielt Sicherheit abklären.","section":"4.5.2"},{"id":"gb98-k-against_domineering-1","domain":"against_domineering","type":"Einordnung","question":"Was unterscheidet „Hinwenden als Kontrolle“ in der beobachteten Interaktion?","correct":"Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","alternatives":["Die Reaktion provoziert einen Schlagabtausch oder fordert das Gegenüber heraus.","Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein."],"why":"Kapitel 4.5.3: Die Reaktion versucht, Gehorsam oder Unterordnung statt Dialog herzustellen.","section":"4.5.3"},{"id":"gb98-k-against_domineering-2","domain":"against_domineering","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Hinwenden als Kontrolle“?","correct":"B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","alternatives":["B antwortet auf Kontakt mit offensiver Provokation.","Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später."],"why":"Der beobachtbare Hinweis ist: B nutzt das Angebot, um As Handlungsspielraum zu bestimmen.","section":"4.5.3"},{"id":"gb98-k-against_domineering-3","domain":"against_domineering","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Hinwenden als Kontrolle“ am ehesten?","correct":"Wessen Wahlfreiheit wird gerade eingeschränkt?","alternatives":["Wird hier gerade Verbindung gesucht oder eine Auseinandersetzung angeheizt?","Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","Welche Grenze wird gesetzt, und welche Verbindung bleibt möglich?"],"why":"Ohne Gedankenlesen nachfragen: Wessen Wahlfreiheit wird gerade eingeschränkt?","section":"4.5.3"},{"id":"gb98-k-against_domineering-4","domain":"against_domineering","type":"Transfer","question":"Wie würdest du bei „Hinwenden als Kontrolle“ zunächst professionell weiterarbeiten?","correct":"Machtanspruch und Freiwilligkeit klären; bei Zwang Sicherheit priorisieren.","alternatives":["Den Machtkampf unterbrechen, sicheren Rahmen und Tempo vereinbaren.","Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten.","Das Nein als gültige Grenze anerkennen; nicht als Liebesentzug interpretieren."],"why":"Vorrangiger Arbeitsschritt: Machtanspruch und Freiwilligkeit klären; bei Zwang Sicherheit priorisieren. Grenzen: Kontrollverhalten bei Furcht, Isolation oder Drohungen nicht als normalen Streit behandeln.","section":"4.5.3"},{"id":"gb98-k-against_criticism-1","domain":"against_criticism","type":"Einordnung","question":"Was unterscheidet „Hinwenden als Charakterkritik“ in der beobachteten Interaktion?","correct":"Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","alternatives":["Die Reaktion auf Kontakt enthält Abwertung oder demonstrative Überlegenheit.","Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","Ein Kontaktversuch mit herabsetzender, provozierender oder kontrollierender Qualität."],"why":"Kapitel 4.5.4: Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","section":"4.5.4"},{"id":"gb98-k-against_criticism-2","domain":"against_criticism","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Hinwenden als Charakterkritik“?","correct":"Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","alternatives":["B beantwortet As Kontaktversuch mit einer Herabsetzung der Person.","B reagiert, als sei schon eine Anklage ausgesprochen worden.","A richtet eine negative, gegen Bs Person oder Autonomie gerichtete Äußerung an B."],"why":"Der beobachtbare Hinweis ist: Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","section":"4.5.4"},{"id":"gb98-k-against_criticism-3","domain":"against_criticism","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Hinwenden als Charakterkritik“ am ehesten?","correct":"Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","alternatives":["Welcher Satz verletzt gerade Würde und Gleichwertigkeit?","Welche Befürchtung hört B in der eigentlichen Äußerung?","Was wird hier zum Kontaktangebot, obwohl es gleichzeitig verletzt?"],"why":"Ohne Gedankenlesen nachfragen: Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","section":"4.5.4"},{"id":"gb98-k-against_criticism-4","domain":"against_criticism","type":"Transfer","question":"Wie würdest du bei „Hinwenden als Charakterkritik“ zunächst professionell weiterarbeiten?","correct":"Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten.","alternatives":["Abwertung klar begrenzen und die zugrunde liegende Beschwerde konkretisieren.","Abwehr anerkennen, ursprüngliche Bitte wieder sichtbar machen und Verantwortung differenzieren.","Abwertung begrenzen und das mögliche Anliegen dahinter vorsichtig erfragen."],"why":"Vorrangiger Arbeitsschritt: Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten. Grenzen: Nicht jede ärgerliche Beschwerde ist Kritik im Sinne eines Persönlichkeitsangriffs.","section":"4.5.4"},{"id":"gb98-k-against_defensiveness-1","domain":"against_defensiveness","type":"Einordnung","question":"Was unterscheidet „Hinwenden als Abwehr“ in der beobachteten Interaktion?","correct":"Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","alternatives":["Statt auf das Kontaktangebot einzugehen, greift B As Persönlichkeit an.","Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen."],"why":"Kapitel 4.5.5: Die Antwort auf einen Kontaktversuch wehrt vorschnell Verantwortung ab oder kehrt Schuld um.","section":"4.5.5"},{"id":"gb98-k-against_defensiveness-2","domain":"against_defensiveness","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Hinwenden als Abwehr“?","correct":"B reagiert, als sei schon eine Anklage ausgesprochen worden.","alternatives":["Die Antwort verallgemeinert eine Situation zu einem Charakterdefizit.","B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung."],"why":"Der beobachtbare Hinweis ist: B reagiert, als sei schon eine Anklage ausgesprochen worden.","section":"4.5.5"},{"id":"gb98-k-against_defensiveness-3","domain":"against_defensiveness","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Hinwenden als Abwehr“ am ehesten?","correct":"Welche Befürchtung hört B in der eigentlichen Äußerung?","alternatives":["Was wäre die konkrete Beschwerde ohne Angriff auf die Person?","Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","Was genau macht das Zuhören für A hier spürbar?"],"why":"Ohne Gedankenlesen nachfragen: Welche Befürchtung hört B in der eigentlichen Äußerung?","section":"4.5.5"},{"id":"gb98-k-against_defensiveness-4","domain":"against_defensiveness","type":"Transfer","question":"Wie würdest du bei „Hinwenden als Abwehr“ zunächst professionell weiterarbeiten?","correct":"Abwehr anerkennen, ursprüngliche Bitte wieder sichtbar machen und Verantwortung differenzieren.","alternatives":["Zwischen Beschwerde und globalem Urteil unterscheiden; respektvolles Sprechen anbieten.","Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen."],"why":"Vorrangiger Arbeitsschritt: Abwehr anerkennen, ursprüngliche Bitte wieder sichtbar machen und Verantwortung differenzieren. Grenzen: Bei realen Anschuldigungen nicht automatisch gleiche Verantwortung unterstellen.","section":"4.5.5"},{"id":"gb98-k-away_preoccupied-1","domain":"away_preoccupied","type":"Einordnung","question":"Was unterscheidet „Abwesend durch Beschäftigung“ in der beobachteten Interaktion?","correct":"Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","alternatives":["Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","Ein ähnlicher Kontaktversuch wird nach passiver oder ausbleibender Reaktion wiederholt."],"why":"Kapitel 4.6.1: Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","section":"4.6.1"},{"id":"gb98-k-away_preoccupied-2","domain":"away_preoccupied","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Abwesend durch Beschäftigung“?","correct":"B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","alternatives":["B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","A erneuert erkennbar dasselbe ursprüngliche Anliegen nach ungenügender Reaktion."],"why":"Der beobachtbare Hinweis ist: B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","section":"4.6.1"},{"id":"gb98-k-away_preoccupied-3","domain":"away_preoccupied","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Abwesend durch Beschäftigung“ am ehesten?","correct":"War die Einladung für B überhaupt wahrnehmbar?","alternatives":["Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","Was wurde beim ersten Versuch angeboten und wie wurde darauf reagiert?"],"why":"Ohne Gedankenlesen nachfragen: War die Einladung für B überhaupt wahrnehmbar?","section":"4.6.1"},{"id":"gb98-k-away_preoccupied-4","domain":"away_preoccupied","type":"Transfer","question":"Wie würdest du bei „Abwesend durch Beschäftigung“ zunächst professionell weiterarbeiten?","correct":"Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","alternatives":["Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen.","Beobachtung benennen, Wirkung erfragen und Gründe offenlassen.","Erste Reaktion benennen, wiederholtes Angebot würdigen und nach Wirkung fragen."],"why":"Vorrangiger Arbeitsschritt: Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln. Grenzen: Arbeit, Schwerhörigkeit oder Neurodiversität sind keine Beweise fehlender Bindung.","section":"4.6.1"},{"id":"gb98-k-away_interrupt-1","domain":"away_interrupt","type":"Einordnung","question":"Was unterscheidet „Unterbrechendes Abwenden“ in der beobachteten Interaktion?","correct":"Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","alternatives":["Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen."],"why":"Kapitel 4.6.2: Bs Antwort unterbricht As Bid und verlagert den Gesprächsfokus.","section":"4.6.2"},{"id":"gb98-k-away_interrupt-2","domain":"away_interrupt","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Unterbrechendes Abwenden“?","correct":"B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","alternatives":["B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung."],"why":"Der beobachtbare Hinweis ist: B fällt A ins Wort, ohne das eigentliche Kontaktanliegen aufzunehmen.","section":"4.6.2"},{"id":"gb98-k-away_interrupt-3","domain":"away_interrupt","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Unterbrechendes Abwenden“ am ehesten?","correct":"Was ist mit dem ursprünglichen Angebot passiert?","alternatives":["War die Einladung für B überhaupt wahrnehmbar?","Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","Was genau macht das Zuhören für A hier spürbar?"],"why":"Ohne Gedankenlesen nachfragen: Was ist mit dem ursprünglichen Angebot passiert?","section":"4.6.2"},{"id":"gb98-k-away_interrupt-4","domain":"away_interrupt","type":"Transfer","question":"Wie würdest du bei „Unterbrechendes Abwenden“ zunächst professionell weiterarbeiten?","correct":"Unterbrechung freundlich sichtbar machen; As Aussage wieder Raum geben.","alternatives":["Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","Beobachtung benennen, Wirkung erfragen und Gründe offenlassen.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen."],"why":"Vorrangiger Arbeitsschritt: Unterbrechung freundlich sichtbar machen; As Aussage wieder Raum geben. Grenzen: Unterbrechung kann auch aus Stress oder Kommunikationsstil entstehen; Muster prüfen.","section":"4.6.2"},{"id":"gb98-k-away_disregard-1","domain":"away_disregard","type":"Einordnung","question":"Was unterscheidet „Ignorierendes Abwenden“ in der beobachteten Interaktion?","correct":"Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","alternatives":["Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist.","Ein Bid wird wahrgenommen, aber nur minimal beantwortet; die Antwort muss bemerkbar sein.","Eine bereits wechselseitige Unterhaltung bricht auffällig und abrupt ab."],"why":"Kapitel 4.6.3: Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","section":"4.6.3"},{"id":"gb98-k-away_disregard-2","domain":"away_disregard","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Ignorierendes Abwenden“?","correct":"B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","alternatives":["B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht.","B registriert den Kontaktversuch und zeigt nur sehr wenig erkennbare Reaktion.","Nach erkennbarer beidseitiger Interaktion beendet eine Person den Austausch unvermittelt."],"why":"Der beobachtbare Hinweis ist: B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","section":"4.6.3"},{"id":"gb98-k-away_disregard-3","domain":"away_disregard","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Ignorierendes Abwenden“ am ehesten?","correct":"Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","alternatives":["War die Einladung für B überhaupt wahrnehmbar?","Woran erkennt A, dass B das Angebot überhaupt wahrgenommen hat?","War das ein natürlicher Abschluss oder ein abrupter Kontaktabbruch?"],"why":"Ohne Gedankenlesen nachfragen: Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","section":"4.6.3"},{"id":"gb98-k-away_disregard-4","domain":"away_disregard","type":"Transfer","question":"Wie würdest du bei „Ignorierendes Abwenden“ zunächst professionell weiterarbeiten?","correct":"Beobachtung benennen, Wirkung erfragen und Gründe offenlassen.","alternatives":["Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln.","Minimalreaktion benennen, ohne sie mit Abwertung gleichzusetzen.","Den Bruch behutsam markieren und den Grund erfragen, ohne Absicht festzulegen."],"why":"Vorrangiger Arbeitsschritt: Beobachtung benennen, Wirkung erfragen und Gründe offenlassen. Grenzen: Keine Absicht aus Schweigen beweisen; Sicherheit, Aufmerksamkeit und individuelle Unterschiede prüfen.","section":"4.6.3"},{"id":"gb98-k-nonbid-1","domain":"nonbid","type":"Einordnung","question":"Was unterscheidet „Kein an Partner gerichtetes Bid“ in der beobachteten Interaktion?","correct":"Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","alternatives":["Ein erkennbar an das Gegenüber gerichtetes nonverbales Kontaktangebot.","Eine einfache an den Partner gerichtete Bemerkung; noch keine persönliche Gefühlsöffnung.","Die andere Person reagiert auf ein Bid nicht wahrnehmbar, weil sie anderweitig absorbiert ist."],"why":"Kapitel 4.2.3: Nicht jede Äußerung oder Blickbewegung will den Partner zu Kontakt einladen.","section":"4.2.3"},{"id":"gb98-k-nonbid-2","domain":"nonbid","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Kein an Partner gerichtetes Bid“?","correct":"Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","alternatives":["A zeigt B etwas, hält es hin und wartet auf eine wahrnehmbare Reaktion.","A äußert eine Beobachtung oder Alltagstatsache direkt zu B.","B bleibt mit etwas anderem beschäftigt, das Kontaktangebot erreicht B scheinbar nicht."],"why":"Der beobachtbare Hinweis ist: Die Handlung richtet sich nicht erkennbar an B oder setzt kein vollendetes Angebot.","section":"4.2.3"},{"id":"gb98-k-nonbid-3","domain":"nonbid","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Kein an Partner gerichtetes Bid“ am ehesten?","correct":"Wurde hier überhaupt ein Kontaktversuch an B gemacht?","alternatives":["Haben Sie bemerkt, dass gerade ohne Worte Kontakt angeboten wurde?","War das eine Information oder auch ein Wunsch nach gemeinsamem Kontakt?","War die Einladung für B überhaupt wahrnehmbar?"],"why":"Ohne Gedankenlesen nachfragen: Wurde hier überhaupt ein Kontaktversuch an B gemacht?","section":"4.2.3"},{"id":"gb98-k-nonbid-4","domain":"nonbid","type":"Transfer","question":"Wie würdest du bei „Kein an Partner gerichtetes Bid“ zunächst professionell weiterarbeiten?","correct":"Nicht jedes Verhalten als Beziehungssignal werten; die tatsächliche Adressierung klären.","alternatives":["Ein sichtbares stilles Angebot beschreiben, B nach eigener Wahrnehmung fragen.","Niedrigschwelliges Kontaktangebot wahrnehmen, ohne eine versteckte Emotion zu behaupten.","Kontext der Nichtreaktion prüfen und einen besseren Zeitpunkt verhandeln."],"why":"Vorrangiger Arbeitsschritt: Nicht jedes Verhalten als Beziehungssignal werten; die tatsächliche Adressierung klären. Grenzen: Nicht aus Selbstgesprächen, Telefonaten oder flüchtigen Blicken Bids machen.","section":"4.2.3"},{"id":"gb98-k-boundary-1","domain":"boundary","type":"Einordnung","question":"Was unterscheidet „Freiwillige Grenze statt Zurückweisung“ in der beobachteten Interaktion?","correct":"Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","alternatives":["Ein wahrnehmbares Kontaktangebot wird übergangen, ohne erkennbare Antwort.","Das Angebot wird erkennbar beantwortet; Energie und inhaltliche Erweiterung bleiben gering.","Das Bid wird erkennbar willkommen geheißen und ernsthaft aufgegriffen."],"why":"Kapitel 4.2 / 4.4–4.6; professionelle Ergänzung: Ein Nein oder zeitlicher Aufschub kann eine respektvolle Kontaktreaktion sein.","section":"4.2 / 4.4–4.6; professionelle Ergänzung"},{"id":"gb98-k-boundary-2","domain":"boundary","type":"Signal","question":"Welcher Hinweis spricht in dieser Szene besonders für „Freiwillige Grenze statt Zurückweisung“?","correct":"B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","alternatives":["B ignoriert As deutliches Angebot im gemeinsamen Aufmerksamkeitsraum.","B wendet sich kurz zu oder unterbricht Tätigkeit und beantwortet das Anliegen knapp.","B richtet Aufmerksamkeit auf A und fragt nach oder spiegelt die Bedeutung."],"why":"Der beobachtbare Hinweis ist: B antwortet auf das Bid mit einer klaren Grenze und gegebenenfalls einem Angebot für später.","section":"4.2 / 4.4–4.6; professionelle Ergänzung"},{"id":"gb98-k-boundary-3","domain":"boundary","type":"Beraterfrage","question":"Welche überprüfende Frage passt bei „Freiwillige Grenze statt Zurückweisung“ am ehesten?","correct":"Welche Grenze wird gesetzt, und welche Verbindung bleibt möglich?","alternatives":["Wie unterscheiden sich Nichtwahrnehmen und bewusstes Nichtantworten im beobachtbaren Verhalten?","Welche konkrete Handlung zeigt hier eine Antwort statt Ignorieren?","Was genau macht das Zuhören für A hier spürbar?"],"why":"Ohne Gedankenlesen nachfragen: Welche Grenze wird gesetzt, und welche Verbindung bleibt möglich?","section":"4.2 / 4.4–4.6; professionelle Ergänzung"},{"id":"gb98-k-boundary-4","domain":"boundary","type":"Transfer","question":"Wie würdest du bei „Freiwillige Grenze statt Zurückweisung“ zunächst professionell weiterarbeiten?","correct":"Das Nein als gültige Grenze anerkennen; nicht als Liebesentzug interpretieren.","alternatives":["Beobachtung benennen, Wirkung erfragen und Gründe offenlassen.","Knappen Kontakt würdigen; ohne Bedarf keine emotionale Intensität erzwingen.","Die zugewandte Reaktion konkret würdigen; nicht bloß Redemenge zählen."],"why":"Vorrangiger Arbeitsschritt: Das Nein als gültige Grenze anerkennen; nicht als Liebesentzug interpretieren. Grenzen: Bei Druck, Angst, kontrollierendem Verhalten oder Zwang keine „Turning-Toward-Pflicht“ vermitteln.","section":"4.2 / 4.4–4.6; professionelle Ergänzung"}],"scope":"Eigenständig formulierte fiktive Fälle. Level-2-Manual Kapitel 4. Nicht das offizielle Gottman-Coding. Grenzen sind eine eigenständige professionelle Ergänzung."};
